/* TYT matematik 1–120: özgün şekil ve ifadeler üzerinden bireysel çözüm analizi. */
(function(){
const rows={};
function M(n,title,topic,page,tests,knowledge,reasoning,trap,concept,why,stem,options,answer,explanation){rows[`q-tyt-matematik-${String(n).padStart(3,'0')}`]={title,topic,lessonIds:[],studyRefs:[{book:'TYT-mat',page,title:topic}],tests,knowledge,reasoning,trap,connections:[{concept,why}],variation:{stem,options,answer,explanation},status:'reviewed',keyCheck:'matches',note:''};}
M(1,'Bir dilimin üçte biri','Rasyonel sayılarda işlemler',26,'Bütünün dörtte birini tekrar üç eş parçaya ayırırken kesirleri çarpmayı ölçer.',['İlk paylaşımda her dilim bütünün 1/4 üdür.','Bir parçanın üçte biri, bütünün üçte biriyle aynı miktar değildir.'],['Cem e dört dilimin tamamı değil tek dilim paylaştırılır.','Cem in payı (1/4) × (1/3) = 1/12; D. Toplam on iki eş parça düşünmek sonucu doğrular.'],'Payda olarak 4 + 3 kullanmak veya yalnız ikinci paylaşımı görüp 1/3 demek.','İç içe oran','İkinci oranın referansı ilk dilimdir; bütüne geçerken iki oran çarpılır.','Pastanın beşte biri iki kişiye eşit paylaştırılıyor. Kişi başına bütünün ne kadarı düşer?',['1/2','1/5','1/7','1/10','2/5'],3,'Her kişi beşte birlik parçanın yarısını, yani bütünün 1/10 unu alır.');
M(2,'Üç satırda ortak sonuç','Tam sayılarla işlemler',10,'Toplama, çıkarma ve çarpmayı eksi işaretleriyle doğru uygulayarak bütün satırlarda aynı sonucu sağlayan sıralamayı buldurur.',['Negatif sayıyı çıkarmak pozitif eklemek demektir.','Zıt işaretli sayıların çarpımı negatiftir; iki negatif sayının toplamı negatiftir.'],['I için − 2 − 2 = −4; II için 2 × (−2) = −4.','III için − 2 + (−2) = −4 olur. Sıra çıkarma–çarpma–toplama; C. Her sembol bir kez kullanılmıştır.'],'İki eksi görünce işlem türünden bağımsız pozitif sonuç beklemek; toplama ve çarpma işaret kuralları aynı değildir.','Kısıtlı yerleştirme','Bir satırdaki seçimi diğer satırlarla ortak sonuç ve tek kullanım koşulu sınırlar.','−3,3 sayılarının çarpımıyla − 3,−3 sayılarının toplamı sırasıyla kaçtır?',['−9,−6','9,6','−6,−9','0,6','9,−6'],0,'Zıt işaretli çarpım − 9; iki negatifin toplamı − 6’dır.');
M(3,'Dokuzla bölünen tekrar rakamı','Bölünebilme',19,'Tanımlanan yeni sayı türünde en küçük uygun tekrar uzunluğunu 9’a bölünebilme kuralıyla belirletir.',['9’un katının rakamları toplamı 9’un katıdır.','3,33,333 gibi sayılarda toplam rakam sayısının üç katıdır.'],['3 ve 33, 9’a bölünmez; 333 bölünür.','En küçük üçeş sayı 333/9 = 37’dir. Rakam toplamı 3 + 7 = 10; D. Aranan toplam 333’ün değil n nin rakam toplamıdır.'],'Tanımdaki 9n ile aranan n yi karıştırmak veya ilk görülen 3 rakamını cevaplamak.','Tanımın ters uygulanması','Önce sonuç sayısını koşula uygun en küçük seçip sonra 9’a bölmek, bilinmeyeni doğrudan tahmin etmekten daha sistematiktir.','Bir doğal sayının 9 katı 666 ise sayının rakamları toplamı kaçtır?',['8','9','10','11','12'],3,'666/9 = 74; rakamları toplamı 7 + 4 = 11.');
M(4,'Çokgen sembolünü sayıya çevirmek','Üslü ifadeler',39,'Kenar sayısını hem katsayı hem üs olarak kullanan sembolik tanımı iki faktöre uygulayıp sonucu yeniden kodlamayı ölçer.',['n kenarlı çokgende a yazıyorsa değer n·aⁿ dir.','Şekiller arasındaki çarpma, içteki rakamların yalnız çarpılması değildir.'],['Karede 1 değeri 4·1⁴ = 4; üçgende 3 değeri 3·3³ = 81.','Çarpım 324’tür. Karede 3, 4·3⁴ = 324 verdiğinden B seçilir.'],'Üs olarak içteki sayıyı kullanmak veya çokgenin kenar sayısını yalnız katsayı olarak almak.','Kod çözme ve kodlama','Aynı tanım önce sembolden sayıya, sonra seçenek sayısından sembole ters yönde işletilir.','n kenarlı a sembolü n·aⁿ ise üçgende 2 ile karede 1’in çarpımı kaçtır?',['12','24','32','48','96'],4,'Üçgende 2 değeri 24, karede 1 değeri 4; çarpım 96’dır.');
M(5,'Tek çarpımdan parite koşulu','Tek ve çift sayılar',12,'Pozitif tam sayılarda a(b + c) tek koşulunu kuvvetli ifadelerin paritesine taşıyıp her zaman doğru olanı seçtirir.',['Tek çarpımın iki faktörü de tektir.','Pozitif kuvvette tabanın tek–çift durumu değişmez; tek sayının her pozitif kuvveti tektir.'],['a tek, b + c tek olduğundan b ve c zıt paritelidir.','I ve II c veya b nin seçimine bağlıdır. III’te cᵃ + b nin paritesi c + b gibi tektir; yalnız III, B.'],'Bir olası örneği sağlayan önermeyi her zaman doğru sanmak; iki olası b, c paritesi de denenmelidir.','Modüler aritmetik','Üs ifadeleri mod 2’de tabanına indirgenir; büyük üsler hesaplanmadan kesinlik testi yapılır.','a tek ve b çift pozitif tam sayıysa aᵇ + bᵃ nasıldır?',['Çift','Tek','Sıfır','Üçün katı','Belirlenemez'],1,'Tekin kuvveti tek, çiftin pozitif kuvveti çift; toplam tektir.');
M(6,'Şişedeki küçük aralıkları saymak','Rasyonel sayılar ve ölçme',26,'Silindir şişedeki eş yükseklik dilimlerini eş hacim olarak okuyup içilen miktarı kalan sudan ayırır.',['2 litre önce dört, sonra her bölüm beşe ayrıldığından 20 eş aralık vardır.','Her küçük aralık 2/20 = 0,1 litreye karşılık gelir.'],['Şekilde başlangıçtaki 2 litre çizgisinden su düzeyine kadar sekiz küçük aralık eksilmiştir.','İçilen miktar 8 × 0,1 = 0,8 = 4/5 litre; E. Kalan su 1,2 litredir.'],'Kalan suyu içilen su diye cevaplamak veya yalnız dört büyük bölümü sayıp küçük ölçeği atlamak.','Ölçek okuma','Silindirin sabit kesiti, doğrusal yükseklik ölçeğinin hacim için de kullanılmasını sağlar.','3 litrelik silindir 15 eş aralıklı. Düzey beş aralık düşüyor. Kaç litre içilmiştir?',['0,2','0,5','1','1,5','2'],2,'Her aralık 3/15 = 0,2 litre; beş aralık 1 litre eder.');
M(7,'İşlem kutularında zorunlu eşleşmeler','Doğal sayılarla işlemler',10,'1–8 sayılarının birer kez kullanıldığı dört işlem dizisinde çarpma ve bölmenin zorladığı çiftleri ayıklamayı ölçer.',['Farklı pozitif sayıların çarpımı 4 ise çift 1 ve 4’tür.','1,4 kullanıldıktan sonra bölümün 4 olması yalnız 8/2 ile mümkündür.'],['Çarpma satırına 1,4; bölmeye 8,2 yerleşir.','Kalan 3,5,6,7 içinde farkı 4 olan 7 − 3’tür. Toplama için 5 + 6 = 11 kalır; E.'],'Kutuları birbirinden bağımsız çözmek; bir satırda kullanılan sayı başka satırda tekrar kullanılamaz.','Kaynak tüketen eleme','En az olasılıklı çarpma ve bölmeden başlamak kalan seçenekleri hızla daraltır.','1–6 birer kez kullanılacak; çarpım 2, fark 3 olan çiftler ayrılınca kalanların toplamı kaçtır?',['5','6','7','8','9'],4,'Çarpım 1 × 2; kalanlarda fark 6 − 3 = 3; toplama 4 + 5 = 9 kalır.');
M(8,'Tam kısım koşullarını kesiştirmek','Rasyonel sayılar',26,'Bölümün tam kısmını eşitliğe değil bir tamsayı aralığına dönüştürerek iki sembolik koşulun ortak iki basamaklı sayısını buldurur.',['Pozitif sayıda tam kısım 4 ise 4 ≤ x < 5’tir.','19/4’ün tam kısmı 4’tür; çokgenin kenar sayısı bölendir.'],['Altıgen AB için 4 ≤ AB/6 < 5; 24 ≤ AB < 30.','Beşgen AB için 20 ≤ AB < 25. Ortak doğal sayı yalnız 24’tür; A + B = 6, A.'],'Tam kısım 4 koşulunu AB/6 = 4 eşitliği olarak her durumda yazmak; aralık yaklaşımı diğer koşulla birlikte gereklidir.','Aralık kesişimi','Aynı bilinmeyene getirilen iki bağımsız kısıtın kesişimi tek sayıyı belirler.','⌊N/4⌋ = 3 ve ⌊N/5⌋ = 2 ise N hangi aralıktadır?',['8–9','10–11','12–14','15–16','17–19'],2,'İlk koşul 12 ≤ N < 16, ikincisi 10 ≤ N < 15; ortak doğal sayılar 12,13,14.');
M(9,'İki dik yola uzaklık','Konum ve uzaklık',9,'Noktanın doğruya uzaklığını dik doğrultuda karşılaştırarak önce ağaç adlarını, sonra diğer yola göre sıralamayı belirletir.',['Bir noktadan doğruya en kısa uzaklık dik uzaklıktır.','Düşey ana caddeye uzaklık yatay, yatay ara sokağa uzaklık düşey ölçülür.'],['Sağdaki nokta ana caddeye en yakın elma; soldaki en uzak armuttur. Ortadaki cevizdir.','Ara sokağa düşey uzaklıklar soldaki, sağdaki, ortadaki şeklinde artar. Sıra armut–elma–ceviz; B.'],'Noktalar arası eğik mesafeyi veya ağaçların çizim büyüklüğünü yol uzaklığı yerine kullanmak.','Koordinat düşüncesi','İki dik yol eksenler gibi okunursa yatay ve düşey bileşenleri ayrı sıralamak yeterlidir.','Yatay yola yükseklikleri 2,5,3 birim olan A, B, C noktalarının yakından uzağa sırası nedir?',['A–B–C','A–C–B','B–C–A','C–A–B','B–A–C'],1,'Yatay doğruya dik uzaklık yüksekliktir; 2 < 3 < 5.');
M(10,'İki sayma dizisinin ortak terimi','Ardışık sayılar',15,'İleri altışar ve geri beşer saymanın aynı iki basamaklı durakta buluşmasını kalan koşullarıyla buldurur.',['56’dan altışar sayılan sayılar 56 + 6k biçimindedir.','15’e beşer geri sayarak ulaşılabilmesi durak sayısının 5’in katı olmasını gerektirir.'],['İki basamaklı adaylar 62,68,74,80,86,92,98’dir.','Bunların yalnız 80’i 5’e bölünür. AB = 80; A + B = 8, C. 80’den 15’e 13 geri adım vardır.'],'56’yı başlangıç değil ilk adım sonrası sanmak veya yalnız 5’e bölünen herhangi bir sayıyı seçmek.','Kongrüans','N≡56 mod 6 ve N≡0 mod 5 koşulları sınırlı aralıkta ortak terimi belirler.','20’den yedişer sayarken ulaşılan ilk 5 katı, 20’den büyük hangi sayıdır?',['25','30','35','40','55'],4,'27,34,41,48,55 dizisinde ilk 5 katı 55’tir.');
M(11,'Rakam genişliği sekiz olan sayıları saymak','Sayı basamakları',16,'En küçük ve en büyük rakam farkını 8 yapan iki uç çifti ayırıp sıfırın başa gelememesini hesaba katar.',['Farkı 8 olan rakam uçları yalnız 0–8 ve 1–9’dur.','Üç rakam farklıdır; üçüncü rakam uçların kesin arasında bulunmalıdır.'],['0,8 yanına 1–7 arasından yedi seçim gelir; her üçlüde başı sıfır olmayan dört diziliş: 28.','1,9 yanına 2–8 arasından yedi seçim, her biri altı diziliş: 42. Toplam 70; A.'],'Her üçlü için otomatik 3! saymak, sıfırla başlayanları üç basamaklı kabul eder.','Durumlara ayırma','İki uç çifti ayrık olduğundan sayılar iki kez sayılmaz; ayrı sayımlar toplanabilir.','Rakamları farklı üç basamaklı sayılarda uç rakamlar 0 ve 9 sabit. Kaç sayı vardır?',['24','28','32','40','48'],2,'Orta rakam 1–8’den sekiz şekilde; sıfır başta olmayan dört dizilişle 32 sayı.');
M(12,'Radyo ölçeğinde ondalık değer','Ondalık sayılar',27,'Eş aralıklı göstergede etiketlenmeyen küçük çizgilerin birim değerini belirleyip kırmızı ibrenin konumunu okumayı ölçer.',['90 ile 92 arasındaki beş küçük aralık toplam 2 birimdir.','Bir küçük aralık 2/5 = 0,4’tür; işaretler değil aralıklar sayılır.'],['94 çizgisinden kırmızı ibreye üç küçük aralık vardır.','İbre 94 + 3 × 0,4 = 95,2 gösterir; C. Sonuç 94 ve 96 arasında ve 96’ya daha yakındır.'],'İki çizgi arasındaki işaret sayısını aralık sayısıyla karıştırmak veya her küçük çizgiyi 0,2 kabul etmek.','Doğrusal ölçek','Bütün eş aralıklar aynı artışı temsil eder; iki bilinen etiket arası birim hesaplamak yeterlidir.','Ölçekte 12 ile 15 arasında altı eş aralık var. 12’den dört aralık sonraki değer kaçtır?',['13','13,5','14','14,5','15'],2,'Her aralık 0,5; dört aralık 2 artışla 14 verir.');
M(13,'Kesir kutularında olamayan toplam','Rasyonel işlemler',26,'Dört sayının her birini bir kez kullanarak iki kesrin toplamının alabileceği değerleri kontrollü eşleştirmeyle sınar.',['Pay ve payda yer değiştirince değer değişir.','Dört sayıyı iki çifte ayırmanın üç temel yolu vardır; her çift kendi içinde ters çevrilebilir.'],['−4/2 + 8/(−1) = −10; 2/(−1) + 8/(−4) = −4.','−4/8 + (−1)/2 = −1 ve − 4/(−1) + 8/2 = 8 elde edilir. Üç çiftleme ve tersleri incelendiğinde 2 oluşmaz; D.'],'Yalnız birkaç rastgele yerleştirme deneyip olamaz demek; tüm çiftleme türleri kapsanmalıdır.','Sonlu olasılık taraması','Sayıların iki pay–payda grubuna bölünmesi sistematik taramayı küçük ve denetlenebilir tutar.','−2,−1,2,4 sayıları birer kez kullanılıyor. −2/2 + 4/(−1) kaçtır?',['−6','−5','−3','1','5'],1,'İlk kesir − 1, ikincisi − 4; toplam − 5.');
M(14,'İki tek sonuçtan a ve b nin paritesi','Tek ve çift sayılar',12,'Üç ifadenin mod 2 eşdeğerlerini kullanarak iki tekrar paritesinin tek olmak zorunda olduğunu çıkarır.',['a + 5b ve 3a + b aynı paritede, a + b ile eşdeğerdir.','2a + 3b nin paritesi b nin paritesidir.'],['İki tek bir çift olması için tekrar eden a + b paritesi tek, b paritesi çift olmalıdır.','Böylece a tek, b çift. 2a + b ve ab çift, a + b tek; II ve III, E.'],'Üç ifadeyi bağımsız üç koşul sanmak; birinciyle üçüncünün pariteleri her a, b için aynıdır.','Mod 2 sadeleştirme','Çift katsayılar sıfıra, tek katsayılar bire indirgenince cebirsel karmaşıklık azalır.','a tek b çift ise 3a + 2b ve a·b sırasıyla nasıldır?',['Çift–tek','Tek–çift','Tek–tek','Çift–çift','Belirsiz'],1,'3a tek, 2b çift; toplam tek. Çarpımda çift faktör bulunduğundan ab çifttir.');
M(15,'Boy artışından üç rakam','Sayı basamakları',16,'1AB,1BA,1CA arasındaki farkları basamak değerleriyle yazıp rakam sınırlarından tek çözümü buldurur.',['1AB = 100+10A+B dir; harfler rakamdır.','A, B, C sıfırdan farklı olduğundan 1 ile 9 arasında kalır.'],['1BA−1AB = 9(B − A) = 36; B = A + 4.','1CA−1BA = 10(C − B) = 40; C = B + 4 = A + 8. Rakam sınırından A = 1, B = 5, C = 9; toplam 15, A.'],'36 cm artışı doğrudan rakam farkı 36 sanmak veya iki sayıdaki onlar–birler değişimini atlamak.','Basamak cebiri','Harfli sayıyı polinom olarak açmak rakam bulmacasını basit doğrusal denklemlere dönüştürür.','İki basamaklı AB ve BA için BA − AB = 27 ise B − A kaçtır?',['1','2','3','4','9'],2,'Fark 9(B − A) olduğundan 9(B − A) = 27 ve B − A = 3.');
M(16,'Bardağın darasını çıkarmak','Oran orantı',45,'Boş ve dolu tartımlardaki ortak bardak kütlesini çıkararak yalnız su kütlelerinin oranını buldurur.',['Tartım bardakla içindekinin toplam kütlesidir.','Aynı su ve aynı bardakta doluluk oranı su kütlesi oranına eşittir.'],['Tam dolu su kütlesi 400 − 280 = 120 g.','Son durumda su 355 − 280 = 75 g; oran 75/120 = 5/8, E. Bardak kütlesi paya veya paydaya dahil edilmez.'],'355/400 oranını doluluk sanmak; bu iki tartımda değişmeyen 280 g dara vardır.','Ortak bileşeni ayırma','Ölçümlerin farkı sabit kabın katkısını yok eder; fiziksel orana geçmeden bileşenler ayrılır.','Boş kap 150 g, dolu kap 450 g, kısmen dolu kap 330 g. Doluluk oranı nedir?',['1/3','1/2','3/5','2/3','3/4'],2,'Su miktarları 180 ve 300 g; oran 180/300 = 3/5.');
M(17,'Kasa toplamında kuruşları korumak','Ondalık işlemler',27,'Birim fiyatla adet çarpımını her satırda yapıp toplam bedeli verilen paradan çıkararak para üstünü hesaplatır.',['Satır bedeli birim fiyat çarpı adettir.','Ondalık basamaklar hizalanarak toplanır; para işlemleri kuruş cinsinden de yapılabilir.'],['Çikolata 0,99 × 5 = 4,95; süt 1,10; ekmek 1,25 × 3 = 3,75 TL.','Toplam 9,80 TL; para üstü 10 − 9,80 = 0,20 TL, A. Adet sütunundaki 1 diğer ürünlere taşınmaz.'],'0,99’u erken yuvarlayıp sonucu kesin kabul etmek veya birim fiyatları adetle çarpmadan toplamak.','Birim analizi','TL/adet ile adet çarpımı TL verir; farklı satırlar ancak aynı para birimine çevrildikten sonra toplanır.','0,75 TL lik üründen dört, 1,20 TL lik üründen iki tane alana 10 TL’den kaç TL kalır?',['3,6','4','4,6','5,4','6'],2,'Toplam 3 + 2,4 = 5,4 TL; kalan 10 − 5,4 = 4,6 TL.');
M(18,'Büyük çarpımı faktöriyelle göstermek','Temel işlemler',10,'Kent, ilçe, okul, kat ve derslik sayılarını çarpıp ardışık çarpanları faktöriyel oranıyla eşleştirir.',['Her alt birim sayısı bağımsız aynı sayıda tekrarlandığından toplam çarpma ile bulunur.','14!/10! = 11·12·13·14’tür.'],['Toplam derslik 11 × 12 × 13 × 2 × 7’dir.','2 × 7 = 14 olduğundan çarpım 11·12·13·14 = 14!/10!, C. Faktöriyelde iptal edilen küçük çarpanlar sonucu değiştirmemelidir.'],'13 okulun iki katını veya her kattaki yedi dersliği yalnız bir kez eklemek; hiyerarşik çoğalmayı toplama sanmak.','Çarpma ilkesi','İç içe eş grupların toplamı, her düzeydeki grup sayılarının çarpımıdır; faktöriyel yalnız kısa yazımdır.','8·9·10 çarpımı hangi faktöriyel oranına eşittir?',['10!/8!','10!/7!','9!/7!','11!/8!','8!/5!'],1,'10!/7! = 8·9·10; ortak 1’den 7’ye çarpanlar sadeleşir.');
M(19,'Uzun sayının rakam toplamı','Sayı basamakları',16,'10ⁿ den 22 çıkarıp üçe bölmenin oluşturduğu tekrar eden rakam örüntüsünü genelleyerek n yi buldurur.',['(10ⁿ − 1)/3, n tane 3’ten oluşur.','(10ⁿ − 22)/3 bu sayıdan 7 eksiktir; son iki rakam 26 olur.'],['Sonuç n − 2 tane 3 ve ardından 26 biçimindedir.','Rakam toplamı 3(n − 2) + 2 + 6 = 3n + 2 = 44; n = 14, B. Örneğin n = 3 için 326 örüntüyü doğrular.'],'10ⁿ ifadesini n basamaklı sayı sanmak veya sondaki ödünç alma etkisini bütün 3 lere uygulamak.','Örüntüden cebire','Küçük n örnekleri biçimi gösterir; asıl çözüm tekrar sayısını n ile yazıp denklem kurmaktır.','(10ⁿ − 22)/3 sayısının rakamları toplamı 29 ise n kaçtır?',['7','8','9','10','11'],2,'Aynı örüntü 3n + 2 = 29 verir; n = 9.');
M(20,'Basamak sayısında tek–çift koşulu','Tek ve çift sayılar',12,'Kat farkıyla kat başına ortak basamak sayısının çarpımını kullanarak iki parite koşulunu birlikte uygulatır.',['İki kat arası basamak sayısı, kat numaraları farkının mutlak değeriyle ortak basamak sayısının çarpımıdır.','Tek çarpım iki tek faktör gerektirir.'],['Arif–Berk arası tek olduğundan kat başına basamak sayısı ve bu kat farkı tektir.','Berk–Can arası çiftse artık kat farkı çift olmalıdır. E’de |8 − 5| = 3 tek, |5 − 7| = 2 çift; E.'],'Kat numaralarının kendilerinin tekliğine bakıp farkın paritesini unutmamak; aranan yol uzunluğu farkla belirlenir.','Ortak çarpanın bilgisi','İlk gözlem ortak basamak sayısının tekliğini sabitler; ikinci gözlem böylece doğrudan kat farkını sınar.','Kat başına basamak sayısı tek. 3. ve 8. kat arasındaki basamak sayısı nasıldır?',['Tek','Çift','Sıfır','Dördün katı','Belirlenemez'],0,'Kat farkı 5 tek; tek × tek çarpımı tektir.');
M(21,'Etiket altında kalan mavi kareler','Oran orantı',45,'Tüm tablodaki renkli kare sayısından görünenleri çıkarıp gizlenen bölgenin kendi toplamına oranlamayı ölçer.',['24 karenin üçte biri 8 karedir.','Gizli bölgenin oranında payda bütün tablo değil etiket altındaki kare sayısıdır.'],['Görünen mavi kare sayısı 2; etiket altında 8 − 2 = 6 mavi vardır.','Şekilde etiket dört sütun ve üç satırı kapatır: 12 kare. İstenen oran 6/12 = 1/2; A.'],'Gizli altı maviyi tekrar 24’e bölmek; soruda referans bölge etiket altıyla sınırlandırılmıştır.','Bütün–alt küme','Aynı nesnelerin iki farklı evrene göre oranı farklıdır; paydayı istenen bölge belirler.','30 karenin 12 si mavi. 15 kare gizli, görünürde 3 mavi var. Gizli bölgedeki mavi oranı nedir?',['1/5','2/5','3/5','4/5','1'],2,'Gizli mavi 12 − 3 = 9, gizli toplam 15; oran 9/15 = 3/5.');
M(22,'İki çekmecenin ortak yükseklik aralığı','Gerçek sayılarda aralık',29,'Farklı çekmece yüksekliklerini ortak yerden ölçüp lekenin aynı anda iki çizilmiş çekmecede kalacağı aralığı buldurur.',['Sol çekmece yüksekliği 3/5 = 0,6 m; sağ çekmece 2/3 m dir.','Bir noktanın iki düşey bölgede kalması yükseklik aralıklarının kesişmesini gerektirir.'],['Leke solda alttan üçüncü çekmecede: 1,2 < h < 1,8.','Sağda orta çekmecede: 2/3 < h < 4/3. Ortak aralık 1,2 < h < 1,333...; yalnız 1,3 uygundur, B.'],'Çekmece sayısını çizimdeki çizgi sayısıyla karıştırmak veya dolapların üstlerini ortak başlangıç kabul etmek.','Aralık kesişimi','İki ayrı ölçekteki konum bilgisi aynı fiziksel yükseklik değişkenine çevrilince birlikte kullanılabilir.','x, 1,4 ile 2 arasında ve 1 ile 1,6 arasında. Hangisi olabilir?',['1,2','1,3','1,5','1,7','1,9'],2,'Kesişim 1,4 < x < 1,6 olup 1,5 bu aralıktadır.');
M(23,'Tam bölünen çiftlerde zorunlu yerleşim','Bölünebilme',19,'1–10 sayılarını birer kez kullanan beş tam bölmede önce başka eşleşmesi olmayan sayıları yerleştirmeyi ölçer.',['Farklı iki pozitif sayıda tam bölüm için büyük sayı küçük sayının katı olmalıdır.','7’nin bu aralıkta tek mümkün farklı böleni 1’dir; 5 ise 10 ile eşleşmek zorundadır.'],['7/1 = 7 ve 10/5 = 2 sabitlenir.','9/3 = 3 ardından 8/4 = 2 ve 6/2 = 3 kalır. Toplam 7 + 2 + 3 + 2 + 3 = 17; E. Her sayı tam bir kez kullanılmıştır.'],'Bölümün tamsayı olması koşuluna rağmen küçük/büyük kesirler kullanmak veya sayıları tekrar etmek.','Zorunlu eşleşme','Seçenek sayısı en az olan elemanla başlamak bütün düzeni belirler; bu bir eşleme problemidir.','1,2,3,4 sayılarıyla iki tam bölme kuruluyor ve her sayı bir kez kullanılıyor. Bölümler toplamı kaçtır?',['3','4','5','6','7'],2,'3 yalnız 1 ile eşleşir: 3/1 = 3; kalan 4/2 = 2, toplam 5.');
M(24,'Üç karşılaştırmadan ikisi doğru','Rasyonel sıralama',26,'Birbirine sıralı üç alt sınırdan tam ikisinin aşılması koşulunu ortak aralığa dönüştürür.',['1/2 > 1/3 > 1/4’tür.','İki doğru bir yanlış için sayı 1/3’ten büyük, 1/2’den büyük olmamalıdır.'],['x ≤ 1/3 olsa en fazla bir önerme doğru olur; x > 1/2 olsa üçü de doğru olur.','Dolayısıyla 1/3 < x ≤ 1/2; paydaları 24 yapınca 8/24 < x ≤ 12/24. 11/24, D.'],'Üç ifadeden herhangi ikisini bağımsız seçmek; eşiklerin sırası nedeniyle doğru–yanlış desenleri serbest değildir.','Mantıksal koşul','Sayısal eşitsizliklerin birbirini içermesi, tam kaç önermenin doğru olabileceğini sınırlar.','x > 1/2, x > 1/4, x > 1/8 önermelerinden tam ikisi doğru. Hangisi uygundur?',['1/10','1/5','3/8','3/4','1'],2,'3/8, 1/4 ve 1/8’i aşar ama 1/2’yi aşmaz.');
M(25,'Tek olan ifadenin hangisi olduğu zorunlu','Tek ve çift sayılar',12,'a + b ve bunun b, c ile çarpımlarında yalnız bir tek bulunmasından a, b, c paritelerini sırasıyla çıkarır.',['a + b çift olsa üç ifadenin hepsi çift olurdu.','a + b tekse b(a + b) ve c(a + b) sırasıyla b ve c nin paritesini taşır.'],['Tek ifade a + b olmak zorundadır; kalan iki çarpım için b ve c çifttir.','a + b tek ve b çift olduğundan a tektir. a + c ile a + b + c tek, b + c çift; I ve III, E.'],'Bir tane tek ifadenin herhangi biri olabileceğini varsaymak; ortak a + b faktörü bu seçenekleri kısıtlar.','Ortak faktör','Bir ifadenin tekrar eden çarpanını önce belirlemek, üç koşulu tek bir parite zincirine indirger.','x + y tek, y ve z çiftse x + z nasıldır?',['Çift','Tek','Sıfır','Dördün katı','Belirsiz'],1,'y çiftken x + y tek olması x i tek yapar; tek + çift yine tektir.');
M(26,'Kemer deliği aralığı','Oran ve doğrusal artış',45,'Delikler arasındaki aralık sayısını şekilden okuyup iki çevre farkından birim deliğe düşen artışı hesaplatır.',['A birinci, B üçüncü, C altıncı deliktir.','Eş aralıklı delikler çevreye eşit artışlar ekler; delik değil aradaki boşluk sayılır.'],['A–B iki aralıkta 78,1 − 74,3 = 3,8 cm artar; bir aralık 1,9 cm.','B–C üç aralıktır; çevre 78,1 + 3 × 1,9 = 83,8 cm, B.'],'A ile B arasında üç aralık saymak veya 78,1 − 74,3 farkını 4,8 hesaplamak; ondalık çıkarma dikkat gerektirir.','Doğrusal model','Çevre deliğin sıra numarasına doğrusal bağlıdır; iki ölçüm artış katsayısını belirler.','İkinci delikte çevre 70, beşincide 76 cm. Yedinci delikte kaç cm olur?',['78','79','80','82','84'],2,'Üç aralık 6 cm, bir aralık 2 cm; beşinciden yedinciye 4 cm eklenir, 80.');
M(27,'İki sıralı sayının ortak rakamı','Sayı basamakları',16,'İçinde 7 bulunan ardışık rakam üçlüsüyle içinde 3 bulunan üçlünün ortakB rakamını buldurur.',['Sıralı sayıda rakamların sayı içindeki sırası önemli değildir; sıralandıklarında üç ardışık değer oluşur.','A7B için olası rakam kümeleri 567,678,789’dur.'],['3BC için kümeler 123,234,345 olabilir; B bu kümelerden bir rakamdır.','7 li kümelerle 3 lü kümelerin uygun ortak rakamı 5’tir; A = 6, C = 4. A + B + C = 15, D.'],'Rakamların sayı içinde de artan sırada yazılması gerektiğini sanmak; 132 örneği bu varsayımı açıkça çürütür.','Küme kesişimi','İki sayının paylaştığı B, iki ardışık üçlü ailesinin kesişimini belirleyerek adayları daraltır.','A8B ve 4 BC sıralı sayılarsa ortakB hangi rakamdır?',['4','5','6','7','8'],2,'8 li olası küme 678, 4 lü olası küme 456 kesişiminde yalnız 6 bulunur.');
M(28,'Nota sürelerini ortak paydada toplamak','Rasyonel işlemler',26,'Görseldeki sekiz notayı kuyruk ve doluluk özellikleriyle ayırıp sürelerini ortak paydada toplar.',['Dolu kuyruksuz nota 1/4, tek kuyruk 1/8, çift kuyruk 1/16’dır.','İçi boş saplı nota 1/2 süreyi temsil eder.'],['Dizide üç çeyrek, iki sekizlik, iki on altılık ve bir yarımlık nota vardır.','Toplam 3/4 + 2/8 + 2/16 + 1/2 = (12 + 4 + 2 + 8)/16 = 26/16 = 13/8; D.'],'Nota yüksekliğini süre sanmak; süreyi porte üzerindeki konum değil sembolün biçimi belirler.','Sınıflandırıp toplama','Önce aynı sembolleri gruplayıp sonra çarpmak uzun kesir toplamını denetlenebilir hâle getirir.','İki yarımlık, bir çeyreklik ve iki sekizlik notanın toplam süresi nedir?',['1','5/4','3/2','7/4','2'],2,'2 × 1/2 + 1/4 + 2 × 1/8 = 1 + 1/4 + 1/4 = 3/2.');
M(29,'Raf sayısıyla aralık sayısı farklıdır','Oran orantı',45,'Aynı toplam yüksekliğe sahip farklı sayıda rafın aralıklarını ve seçili rafların yerden seviyesini hesaplatır.',['Beş raf dört aralık, altı raf beş aralık oluşturur.','Alttaki ilk raf yer seviyesinde olduğundan n inci rafın yüksekliği (n − 1) aralıktır.'],['Solda aralık 1,2/4 = 0,3; dördüncü raf 3 × 0,3 = 0,9 m.','Sağda aralık 1,2/5 = 0,24; üçüncü raf 2 × 0,24 = 0,48 m. Toplam 1,38 m, A.'],'Yüksekliği doğrudan raf sayısına bölmek veya dördüncü rafı dört aralık yukarıda kabul etmek.','Doğrusal bölme','Uç noktaları ortak olan eş bölmelerde nesne sayısıyla boşluk sayısı arasındaki bir fark sonucu belirler.','1,5 m boyunca dört eş aralıklı rafın üçüncüsü yerden kaç m yüksektedir?',['0,5','0,75','1','1,25','1,5'],2,'Dört raf üç aralık oluşturur; üçüncü raf iki aralık, 2 × 0,5 = 1 m.');
M(30,'İki çizim, iki farklı işlem','Tanımlı işlemler',10,'Köşegen yönüne göre değişen toplama–bölme ve çarpma–bölme tanımlarını rakamların gerçek yerlerine uygular.',['İlk çizimde değer (a + d)/(b + c) dir.','İkinci çizimde değer ad/(bc) dir; aynı konumlar dönüş yönüyle farklı görünür.'],['Sol şekil (10 + 14)/(2 + 4) = 24/6 = 4 verir.','Sağ şekil (x·7)/(14·6) = x/12’dir. Eşitlikten x/12 = 4 ve x = 48; E.'],'Her iki şekle aynı işlem kuralını uygulamak veya sağ şeklin dış bölmelerindeki x ve 7’yi yanlış eşlemek.','Temsilden cebire','Çizim yalnız veriyi kodlar; doğru değişken eşlemesinden sonra çözüm birinci dereceden denklemdir.','Bir sembol (a + d)/(b + c), diğeri ad/(bc). İlkinde 8,2,3,12; ikincide x,5,4,10 var. Eşitlikte x kaçtır?',['4','6','8','10','12'],2,'İlk değer 20/5 = 4; ikinci 10x/20 = x/2, dolayısıyla x = 8.');
M(31,'Farklı rakam sayısı','Sayı basamakları',16,'Sembolle gösterilen değerin sayının kendisi değil farklı rakam türü sayısı olduğunu kullanarak A’nın tekrar oluşturduğu durumları buldurur.',['71024 beş farklı rakam içerir.','3A5’te A = 3 veya 5 olunca değer 2, diğer durumlarda 3; 56A için A = 5 veya 6 olunca 2’dir.'],['Toplamın 5 olması için değerlerin 2 ve 3 olması gerekir.','A = 3 için 2 + 3, A = 6 için 3 + 2; A = 5’te 2 + 2 olur. Uygun A ların toplamı 3 + 6 = 9, B.'],'Rakamların tekrar sayısını toplamak veya A = 5’i iki sembolde tekrar yarattığı için uygun sanmak.','Durum tablosu','Özel değerler yalnız sabit rakamlarla çakışan A lardır; diğer bütün rakamlar aynı genel duruma düşer.','Farklı rakam sayısını gösteren d için d(4A7) = 2 olması adına A hangi kümededir?',['{0,1}','{4,7}','{2,7}','{4,5,7}','Bütün rakamlar'],1,'A sabit iki rakamdan biri olursa yalnız 4 ve 7 kalır; başka rakam üçüncü tür ekler.');
M(32,'Dört durumlu lambada kalan hesabı','Periyodik problemler',25,'Kapalı–loş–gün–parlak çevrimindeki ardışık geçiş sayılarının mod 4 değerlerini pariteye dönüştürür.',['Lamba dört çekişte başlangıç durumuna döner.','Kapalıdan parlağa 3, parlaktan güne 3, günden kapalıya 2 mod 4 çekiş gerekir.'],['A ve B,4’ün katından 3 fazla olduğundan tektir; C,4’ün katından 2 fazla olduğundan çifttir.','E’de C(A + B), çift faktör içerir; diğer seçenekler tek olur. C(A + B) çift; E.'],'B’yi başlangıçtaki kapalı durumdan saymak; her aşama önceki aşamanın son durumundan başlar.','Durum makinesi','Dört durumun çevrimi modüler aritmetik sağlar; büyük çekiş sayıları yerine yalnız kalanlar izlenir.','Üç durumlu çevrimde A→B→C→A var. A’dan başlayıp 14 geçiş sonra hangi durumdasınız?',['A','B','C','A veya B','Belirsiz'],2,'14’ün 3 ile bölümünden kalan 2; A’dan iki geçiş C’ye getirir.');
M(33,'İki basamaklı ifadesini çarpan sanmamak','Sayı basamakları',16,'AB + BC = CA − 1 eşitliğini basamak cebirine çevirip rakamların farklılığıyla sonlu çözüm sayısını buldurur.',['AB = 10A+B, BC = 10B+C, CA = 10C+A dır.','A, B, C sıfırdan farklı ve birbirinden farklı rakamlardır.'],['Eşitlikten 9A+11B+1 = 9C; mod 9’da 2B+1≡0, dolayısıyla B = 4.','C = A + 5 olduğundan A = 1,2,3 uygundur; A = 4 yasak, daha büyükte C rakam olmaz. Üç ABC vardır; C.'],'Metindeki iki basamaklı CA’yı 2·CA diye okumak veya B = 4 ile çakışan A = 4’ü saymak.','Bölünebilme ve basamak','Mod 9 önce bir rakamı belirler; kalan doğrusal ilişki diğerlerini aralık ve farklılıkla sınırlar.','AB + BC = CA − 1 koşulunda B = 4 ise A = 2 için C kaçtır?',['3','4','5','6','7'],4,'9A+45 = 9C, yani C = A + 5; A = 2 iken C = 7.');
M(34,'Bire tamamlayan kesir çiftleri','Rasyonel işlemler',26,'Beş kesirden toplamı 1 olan iki ayrık çift kurarken sadeleştirme ve tamamlayıcı kesir fikrini kullanır.',['8/12 = 2/3,6/8 = 3/4,9/36 = 1/4’tür.','x in 1’e tamamlayıcısı 1 − x tir; verilenler içinde bu değerin bulunması gerekir.'],['1/3 ile 2/3,3/4 ile 1/4 iki geçerli çifttir.','1/6’nın tamamlayıcısı 5/6 listede yoktur; gruplarda yer alamayan 1/6, A. Her kesir en fazla bir kez kullanılır.'],'Pay ve paydaları ayrı ayrı toplayarak kesirleri toplamak veya sadeleşmiş eşdeğerleri görememek.','Tamamlayıcı arama','Toplamı belirli iki elemanlı grup sorusu, her eleman için eksik parçayı hesaplama problemine dönüşür.','2/5,3/5,1/4,3/4,1/3 içinden toplamı 1 olan iki çift ayrılınca hangisi kalır?',['2/5','3/5','1/4','3/4','1/3'],4,'2/5 + 3/5 ve 1/4 + 3/4 = 1; 1/3’ün 2/3 tamamlayıcısı yoktur.');
M(35,'Gerçek ama rasyonel olmayan sayı','Sayı kümeleri',9,'İrrasyonel sayı seçerken gerçek olma ve rasyonel olmama koşullarını birlikte uygulatır.',['İrrasyonel sayılar gerçek olup iki tam sayının oranı biçiminde yazılamaz.','√2 irrasyoneldir; küpkök 8 = 2,−1 ve 1/3 rasyoneldir.'],['C deki√2 gerçek ve irrasyoneldir.','E deki i + 3 gerçek sayı değildir; irrasyonel diye seçilemez. Diğer seçenekler rasyoneldir; C. Kök sembolü taşımak tek başına irrasyonellik kanıtı değildir.'],'Her köklü sayıyı irrasyonel veya her rasyonel olmayan karmaşık sayıyı gerçek irrasyonel sanmak.','Küme içerilmesi','İrrasyoneller gerçek sayıların bir alt kümesidir; karmaşık düzlemdeki gerçek olmayan sayılar bu kümeye dahil değildir.','Hangisi irrasyonel gerçek sayıdır?',['√9','0,25','−7/3','√5','2 + i'],3,'√5 tam kare olmayan pozitif tam sayının karekökü olduğundan irrasyonel ve gerçektir.');
M(36,'Eşit elma kasalarından sınıf paritesi','Tek ve çift sayılar',12,'Aynı N elmalı kasadan bir sınıfa dağıtınca 3 artması, diğerine 2 eksik kalması koşullarından öğrenci farkı ve çarpımını belirler.',['A sınıfı öğrenci sayısı N − 3, B sınıfı N + 2’dir.','Aralarında tek fark bulunan iki tam sayının pariteleri zıttır; çarpımları çifttir.'],['Sınıf mevcudu farkı (N + 2) − (N − 3) = 5, daima tektir; II.','N − 3 ile N + 2 zıt pariteli olduğundan çarpım çift; III. N’nin kendisi tek de çift de olabilir; II ve III, D.'],'Her kasada kalan elma sayısının tekliğinden başlangıç elma sayısının tekliğini çıkarmak.','Farktan parite','Bilinmeyen ortak N fark alınınca yok olur; sayılar tek tek bilinmeden bazı özellikleri kesin belirlenebilir.','İki doğal sayı x − 2 ve x + 5 ise toplamları nasıldır?',['Daima çift','Daima tek','Daima asal','Daima negatif','Belirsiz'],1,'Toplam 2x + 3’tür; 2x çift olduğundan toplam tektir.');
M(37,'Termometrede iki etiketten birim bulmak','Ondalık ve ölçek',27,'Her termometrenin kendi ölçeğini ayrı okuyup kırmızı düzeyi eş aralık değerleriyle karşılaştırır.',['Ölçek birimi iki sayı farkının aralık sayısına bölünmesiyle bulunur.','Aynı çizgi uzunluğu farklı termometrelerde aynı sıcaklık artışı anlamına gelmez.'],['C’de 0 ile 30 arasında altı aralık vardır; her biri 5 °C.','Kırmızı düzey 0’ın üç aralık üzerinde olduğundan 15 °C gösterir; C. Diğer göstergelerin etiketleri ve basamak değerleri aynı değildir.'],'Tüm şekillerde kırmızı yükseklikleri görsel olarak karşılaştırmak; önce her aletin ölçek katsayısı belirlenmelidir.','Doğrusal dönüşüm','Ölçekli çizimden sayıya geçiş, başlangıç değeri artı aralık sayısı çarpı birim artıştır.','Termometrede − 10 ile 20 arasında altı eş aralık var. −10’dan beş aralık yukarı kaç derecedir?',['5','10','15','20','25'],2,'Birim 5 °C;−10 + 5 × 5 = 15 °C.');
M(38,'Tombala satırlarında basamak denklemi','Sayı basamakları',16,'İki satırın eşit toplamını A ve B rakamlarının basamak değerleriyle yazıp AB + BA’yı hesaplatır.',['A2 = 10A+2, B4 = 10B+4,3B = 30 + B,1A = 10 + A dır.','AB + BA = 11(A + B) olduğundan son adımda ayrı iki sayı hesaplamak şart değildir.'],['Üst satır 78+10A, alt satır 95 + A+11B dir.','Eşitlik 9A−11B = 17 verir; rakam çözümü A = 8, B = 5. Toplam 11 × 13 = 143; E.'],'A2 gibi ifadeyi A·2 sanmak veya satırdaki 1A’nın A katsayısını 10 almak.','Diyofant denklem','Rakamların 0–9 aralığı, iki bilinmeyenli doğrusal denklemde sonlu ve dar bir çözüm kümesi sağlar. Denklemde her A seçimi için B’nin tamsayı ve rakam olması ayrıca kontrol edilir.','AB + BA = 121 ise A + B kaçtır?',['9','10','11','12','13'],2,'Toplam 11(A + B) olduğundan A + B = 121/11 = 11.');
M(39,'Ortadaki rakamın karesi uç rakamlar','Sayı basamakları',16,'Kare sayının iki uç rakamı hangi sırayla oluşturabileceğini iki olasılıkla inceler ve ortakB’yi tutarlı seçer.',['İki basamaklı rakam kareleri 16,25,36,49,64,81’dir.','AB 1’de B² uç rakamlar A ve 1’i, BC 4’te C² uç rakamlar B ve 4’ü içerir.'],['AB 1 için B² = 16 veya 81; adaylar(A, B) = (6,4),(8,9).','B = 4 ikinci sayıda 44 gerektirir, kare değildir. B = 9 ise 49 = C², C = 7. Toplam 8 + 9 + 7 = 24; D.'],'Uç rakamların mutlaka sayıdaki sırayla yan yana yazılacağını varsaymak; örnekler her iki sırayı da mümkün kılar.','Adaylar arası tutarlılık','İlk sayının ürettiği iki aday ikinci sayıyla sınanır; ortak rakam bağı iki bulmacayı tek sisteme bağlar.','A52 bitişik sayıysa 5² = 25 koşulundan A kaçtır?',['1','2','3','4','5'],4,'5² = 25 olduğundan uç rakamlar 2 ve 5 olmalıdır; birler 2 ise yüzler A = 5’tir.');
M(40,'Simgelerin sayısı değişmeden kapasite artar','Oran orantı',45,'Büyük simgede dolu hücre sayısını hesaplayıp aynı uygulamaları küçük simge düzeninin yeni toplam hücre sayısına oranlar.',['İlk ekran 3 × 4 = 12, ikinci 5 × 6 = 30 bölmelidir.','Görünüm değişimi uygulama sayısını değiştirmez; yalnız hücre kapasitesi değişir.'],['İlk görünümde 12’nin 2/3’ü, yani 8 uygulama vardır.','İkinci görünümde de 8 hücre doludur; oran 8/30 = 4/15, D. 2/3 oranını doğrudan korumak yanlış olur.'],'Yeni satır veya sütun sayısının tekini payda almak ya da ilk doluluk oranını değişmeden kullanmak.','Korunan sayı','Aynı nesne sayısı farklı büyüklükte evrenlerde farklı oranlar üretir; önce mutlak sayı bulunmalıdır.','20 bölmenin 3/5’i dolu. Aynı simgeler 30 bölmeli düzene taşınınca oran nedir?',['1/5','2/5','3/5','4/5','1/2'],1,'Sayı 12’dir; yeni oran 12/30 = 2/5.');
M(41,'Ondalık basamakların yerini değiştirmek','Ondalık sayılar',27,'Kesri ondalığa çevirip onda birlerle yüzde birlerin yer değiştirmesini yeni kesre dönüştürür.',['13/20 = 65/100 = 0,65’tir.','Basamakların yer değiştirmesi rakamları değiştirir; sayıların değerleri basamak ağırlıklarına bağlıdır.'],['Doğru sonuçtaki onda bir 6, yüzde bir 5’tir; ters yazınca 0,56 oluşur.','0,56 = 56/100 = 14/25; C. İşlem kesrin payıyla paydasını yer değiştirmek değildir.'],'0,65 i0,065 yapmak veya seçeneklerde 0,65’e en yakın kesri aramak.','Basamak değeri','6/10 + 5/100 ile 5/10 + 6/100 farklı sayılardır; yalnız iki rakamın aynı olması eşitliği sağlamaz.','7/20’nin ondalığında onda ve yüzde birler yer değişirse sonuç hangisidir?',['0,35','0,53','0,305','0,035','0,5'],1,'7/20 = 0,35; 3 ve 5 basamak değiştirince 0,53 olur.');
M(42,'Bölümlerin paritesinden c yi bulmak','Tek ve çift sayılar',12,'Çift ve tek tamsayı bölüm koşullarını önce çarpım eşitliğine çevirerek a, b, c nin zorunlu paritelerini çıkarır.',['(a + b)/c çift tamsayıysa a + b çift olduğundan a ve b aynı paritededir.','(a + c)/b tek tamsayıysa a + c ile b aynı paritededir.'],['a ile b aynı olduğundan ikinci koşul c nin çift olmasını gerektirir.','a + b + c çift; abc de c nedeniyle çifttir. a(b + c), a, b tekken tek olabilir. I ve III, D.'],'Kesir ifadesinin çiftliğinden pay ve paydanın ikisini de çift saymak; paydanın paritesi tek başına belirlenmez.','Bölmeden çarpmaya','Bölümün tamsayı olma bilgisini a + b = 2 kc gibi yazmak parite çıkarımını güvenilir hâle getirir.','a, b tek ve c çiftse a(b + c) ve abc nasıldır?',['Çift–çift','Tek–çift','Tek–tek','Çift–tek','Belirsiz'],1,'b + c tek, a tek olduğu için ilk çarpım tek; c nedeniyle ikinci çarpım çift.');
M(43,'Meyve paketlerinde ortak ve ayrık türler','Denklem kurma',33,'Her biri üç paketle yedi meyve alma koşulunu paket boylarına çevirip aynı tür ve tamamen farklı tür alan kişilerin dağılımını ayırır.',['Paket boyları 5,4,3,2,1; adetleri 1,2,3,4,5’tir.','Üç paketle 7 yapma biçimleri 5 + 1 + 1,4 + 2 + 1,3 + 3 + 1,3 + 2 + 2’dir.'],['Aynı türleri alan iki kişi 4 + 2 + 1 düzenini kullanır; iki elma paketi böylece biter.','Merve ve Rabia türleri ayrık olarak 5 + 1 + 1 ile 3 + 2 + 2 alır. Sibel e3 + 3 + 1, yani armut ve ananas kalır; A.'],'Yedi meyveyi yedi paket sanmak veya aynı tür koşulunu yalnız bir ortak meyve türü bulunması diye gevşetmek.','Kapasite ve eşleme','Paket adetleri hangi toplam deseninin kaç kişide kullanılabileceğini sınırlar; miktar ve tür koşulları birlikte çözülür.','Paketler 5,3,3,2,2,1,1,1 meyveli. Üç paketle 7 için 5 li paket kullanılırsa diğer ikisi nedir?',['3 ve 2','3 ve 1','2 ve 2','1 ve 1','5 ve 1'],3,'5’ten sonra iki pakette toplam 2 kalır; yalnız 1 + 1 mümkündür.');
M(44,'Asal olmayan rakamlarla asal sayı','Asal sayılar',17,'Yeni tanımda sayının asal, her rakamının ise asal olmayan rakam olması koşullarını birlikte tarar.',['Asal rakamlar 2,3,5,7’dir; izinli rakamlar 0,1,4,6,8,9’dur.','İki basamaklı asalın birler basamağı izinli kümeden yalnız 1 veya 9 olabilir.'],['Adaylar arasında 11,19,41,61,89 asaldır; 49,69,81,91 gibi bileşikler elenir.','Toplam 11 + 19 + 41 + 61 + 89 = 221; E. Onlar basamağı 0 olamaz,1 ise asal rakam değildir.'],'1’i asal kabul edip 11 ve 19’u elemek veya her rakamı asal olmayan her sayının da asal olmadığını düşünmek.','Yerel ve bütünsel özellik','Rakamların tek tek asal olmaması, oluşturdukları sayının asallığını belirlemez; iki düzey ayrı sınanır.','Hangisi rakamları asal olmadığı hâlde kendisi asal olan sayıdır?',['49','61','81','91','99'],1,'61’in rakamları 6 ve 1 asal değildir; 61 yalnız 1 ve 61’e bölünür.');
M(45,'Ardışık teklerde onlar değişimi','Sayı basamakları',16,'Beş ardışık tek sayının birler toplamının sabitliğini kullanıp 42 lik toplamdan onlar basamaklarının dağılımını çıkarır.',['Beş ardışık tek sayıda birler rakamları 1,3,5,7,9’un bir permütasyonudur.','Bu rakamların toplamı 25; toplam rakam toplamından çıkarılınca onlar toplamı kalır.'],['Onlar basamakları toplamı 42 − 25 = 17’dir.','Birbirine yakın beş onlar rakamı 3,3,3,4,4 olmalıdır; sayılar 35,37,39,41,43. En büyüğün rakam çarpımı 4 × 3 = 12; C.'],'Sayıların toplamını 42 sanmak veya basamak geçişini yok sayıp beşinin onlar basamağını aynı almak.','Taşıma sınırı','Ardışık tek dizisi bir onluk sınırını geçince onlar rakamları iki komşu değerde dağılır; toplam dağılımı belirler.','Beş ardışık tek sayı 25,27,29,31,33 ise en büyüğün rakam çarpımı kaçtır?',['3','6','8','9','12'],3,'En büyük 33’tür; 3 × 3 = 9.');
M(46,'Büyük ama basit kesir','Rasyonel sıralama',26,'5/6’dan büyük olma ve payı paydasından küçük olma koşullarını aynı anda sınar.',['Basit pozitif kesirde pay paydadan küçüktür; değer 1’den küçüktür.','Karşılaştırmada 5/6 = 10/12 ortak paydasını kullanmak uygundur.'],['2/3 = 8/12,3/4 = 9/12; ikisi 10/12’den küçüktür.','11/12 hem 10/12’den büyük hem 1’den küçüktür. 12/12 ve 13/12 basit değildir; C.'],'Büyüklük koşulunu sağlayan 13/12’yi seçip basit kesir koşulunu unutmak veya 12/12’yi basit saymak.','İki eşitsizliğin kesişimi','Aranan değer 5/6 < x < 1 aralığındadır; iki sözel koşul tek açık aralıkta birleştirilebilir.','3/4’ten büyük basit kesir hangisidir?',['2/3','3/5','7/8','8/8','9/8'],2,'7/8,6/8’den büyük ve 1’den küçüktür.');
M(47,'Kesilecek ortak sap uzunluğu','Ondalık işlemler',27,'Yalnız keserek eşitlemede hedef boyun en kısa sap olmak zorunda olduğunu belirleyip fazlalıkları toplar.',['Parça eklenmediği için son ortak uzunluk en kısa sapı aşamaz.','Yalnız üç sap kesildiğinden en kısa 16,8 cm lik sap aynen kalır.'],['Fazlalıklar 17,9 − 16,8 = 1,1; 19,2 − 16,8 = 2,4; 20 − 16,8 = 3,2 cm.','Toplam 1,1 + 2,4 + 3,2 = 6,7 cm; C. Kurdele üstündeki kısım verilmediği için hesaba katılmaz.'],'Dört uzunluğun ortalamasına kesmeye çalışmak; kısa sapı uzatmak mümkün değildir.','En küçük değer kısıtı','Kesme işleminin tek yönlü oluşu hedefi belirler; optimizasyonu ayrıca aramaya gerek kalmaz.','Saplar 12,14,15,19 cm. Yalnız keserek 12 cm ye eşitlenirse toplam kaç cm kesilir?',['8','10','12','14','16'],2,'Fazlalıklar 0,2,3,7; toplam 12 cm.');
M(48,'Yanlış işlemin de doğru sonuç vermesi','Denklem sistemi',33,'A/B = A − B = 3 koşulundan gerçek sayıları bulup çarpımla toplam arasındaki farkı hesaplatır.',['Bölme tanımlı olduğu için B ≠ 0.','A/B = 3 eşitliği A = 3B biçiminde doğrusal ilişki verir.'],['A − B = 3’e A = 3B yazılır:2B = 3, B = 3/2 ve A = 9/2.','Doğru çarpım 27/4, yanlış toplam 6 = 24/4; yanlış cevap 3/4 eksiktir, E.'],'A ve B’yi tamsayı varsayıp çözüm yok demek veya doğru cevapla yanlış cevabı ters çıkarıp negatif sonuç almak.','Aynı sonucu paylaşan işlemler','İşlem hatasının ilk aşamada görünmemesi iki işlem sonucunun eşitliğine dönüşür; ikinci aşama bu özel sayılarda incelenir.','A/B = A − B = 2 ise A + B kaçtır?',['2','3','4','5','6'],4,'A = 2B ve A − B = B = 2; A = 4, toplam 6.');
M(49,'Beş değerden yalnız birinin tekliği','Sayı basamakları',16,'İki basamaklı sayının kendisi, rakam toplamı, çarpımı, farkı ve bölümünün paritelerini birlikte kullanır.',['Bölümün doğal olması onlar rakamının birler rakamına tam bölünmesini gerektirir.','Rakamların toplamıyla farkı aynı paritededir; bunlar tek olsa en az iki tek oluşur.'],['Toplam ve fark çift; rakamlar aynı paritededir. Tek–tek olsalar sayı ve çarpım da tek olur, olmaz.','İki rakam çift olup bölüm tek olmalı; farklı sıfırsız rakamlarda tek uygun sayı 62. Değerler 62,8,12,4,3; toplam 89, A.'],'Son bölümün doğal sayı olmasını unutmak veya toplam ve farkı bağımsız parite seçenekleri sanmak.','Parite ve sonlu tarama','Önce parite aday rakamları daraltır; sonra tam bölüm koşulu tek çifti bırakır.','62 için rakam çarpımıyla onlar/birler oranının toplamı kaçtır?',['9','12','15','18','24'],2,'6 × 2 + 6/2 = 12 + 3 = 15.');
M(50,'On birle çarpmada elde','Sayı basamakları',16,'11 AB çarpımının rakam toplamını basamak taşıması ve mod 9 kontrolüyle A + B’ye bağlar.',['11(10A+B) = 100A+10(A + B) + B dir.','A + B < 10 ise rakam toplamı 2(A + B) çift olur; 15 için elde gerekir.'],['s = A + B ≥ 10 iken normal elde sonrası rakam toplamı 2s − 9 olur.','2s − 9 = 15’den s = 12; C. A = 9 nedeniyle binliğe ek elde oluşsa toplam 2s − 18 olurdu; 15 için tamsayı s çıkmaz.'],'Çarpımın rakam toplamını 11(A + B) sanmak; rakam taşıması toplamı 9’un katları kadar değiştirebilir.','Mod 9 kontrolü','11≡2 mod 9 olduğundan 2(A + B)≡15 çıkar; aday 3 veya 12’den elde koşulu 12’yi bırakır.','39’un 11 katının rakamları toplamı kaçtır?',['9','12','15','18','21'],2,'39 × 11 = 429; 4 + 2 + 9 = 15.');
M(51,'Eş yaylarda uzaklık oranı','Oran orantı',45,'Birer birimlik aralığın beşe bölündüğü radyal ölçekten A ve B’nin merkez uzaklıklarını okuyup gerçek uzunluk ölçeğini taşır.',['Her küçük yarıçap aralığı 0,2 birimdir.','A ve B’nin uzaklıkları aynı ölçekle çizildiğinden gerçek metre oranları çizim oranına eşittir.'],['A,3 ile 4 arasında üçüncü ara yayda:3,6 birim; B,4 ile 5 arasında dördüncüde:4,8.','Oran 4,8/3,6 = 4/3; B uzaklığı 54 × 4/3 = 72 m, C.'],'Yay boyunca çevresel uzaklığı ölçmek; soru merkezden noktaya yarıçap uzaklığını sorar.','Benzer ölçek','Bilinmeyen birim dönüşümünü ayrı bulmak yerine oran almak ortak ölçek katsayısını sadeleştirir.','Ölçekte A’nın uzaklığı 2,4 birim, B’nin uzaklığı 3,6 birim. A gerçek 40 m ise B kaç m dir?',['45','50','55','60','75'],3,'Oran 3,6/2,4 = 1,5; 40 × 1,5 = 60 m.');
M(52,'Bölen onlar rakamıyla uç sayılar','Bölünebilme',19,'Onlar rakamının yüzler ve birler rakamlarını bölmesi, farklılık ve sıfırsızlık altında en büyük ve en küçük sayıyı kurdurur.',['En büyük üç basamaklı sayı önce yüzler, sonra onlar, sonra birler basamağı büyütülerek aranır.','Onlar rakamı iki komşu rakamın ortak böleni olmalı; bütün rakamlar farklıdır.'],['Yüzler 9 için en büyük uygun farklı onlar 3, birler 6; en büyük 936.','Yüzler 1 olursa onlar 1 tekrar eder, olmaz; yüzler 2, onlar 1, birler 3 ile en küçük 213. Fark 936 − 213 = 723; A.'],'Rakamların farklılığını atlayıp 999 veya 111’i almak; bölünebilme koşulu tek başına yeterli değildir.','Sözlük sırası','Uç sayılar basamak önceliğiyle kurulur; küçük basamakta iyileştirme daha büyük basamaktaki kaybı telafi edemez.','Rakamları farklı, sıfırsız ve onlar rakamı 1 olan en küçük üç basamaklı sayı nedir?',['102','112','123','213','312'],3,'Yüzler 1 olamaz; en küçük 2, birler 1 ve 2’den farklı en küçük 3:213.');
M(53,'Dokuz, beş ve on iki koşullarını birleştirmek','Bölünebilme',19,'AAB ve ABA’nın ortak rakam toplamıyla 9’a bölünmesini, son rakamla 5 ve son iki basamakla 4 koşullarını birleştirir.',['Her iki sayının rakam toplamı 2A+B dir.','12’ye bölünme 3 ve 4’e bölünmeyi gerektirir; 5’e bölünen sayı 0 veya 5 ile biter.'],['AAB 5’e bölünüyorsa B = 0 veya 5. B = 5 için 2A+5,9’un katı olmalı; A = 2.','2255’e,25212’ye bölünür. A = 5 veya B = 0 dalları 12 koşulunu sağlamaz. A + B = 7; A.'],'5’e bölünecek sayının hangisi olduğunu baştan kesin seçmek; iki olasılığın da denetlenmesi gerekir.','Koşul kesişimi','Rakam toplamı ve son basamak kuralları farklı bilgiler sağlar; birlikte çok az aday bırakır.','225 ve 252 sayılarından hangisi 12’ye tam bölünür?',['Yalnız 225','Yalnız 252','İkisi','Hiçbiri','Yalnız toplamları'],1,'252’nin rakam toplamı 9 ve son iki basamağı 52,4’ün katı; 12’ye bölünür.');
M(54,'Çarpımda otuzun asal çarpanları','Bölünebilme',19,'AB·BA’nın 30’a bölünmesini 2,3,5 koşullarına ayırıp sıfırsız iki rakamı belirler.',['AB ve BA iki basamaklı olduğundan A ve B sıfır değildir.','30 = 2·3·5; çarpımın 5 faktörü için rakamlardan biri 5 olmalıdır.'],['Diğer rakam 2 faktörünü sağlayacak çift rakamdır.','3’e bölünebilme için A + B,3’ün katı olmalı; 5 yanında 2,4,6,8 içinden yalnız 4 uygundur. A + B = 9; B.'],'Çarpımdaki her sayının ayrı ayrı 30’a bölünmesini istemek; asal çarpanlar iki faktör arasında paylaşılabilir.','Asal çarpan muhasebesi','Bileşik bölünebilme koşulu bağımsız asal gereksinimlere ayrılınca son rakam ve rakam toplamı kuralları birlikte kullanılabilir.','45·54 çarpımının 30’a bölünmesi için hangi faktörler bulunur?',['Yalnız 2','Yalnız 3','Yalnız 5','2,3,5','Yalnız 2 ve 5'],3,'54 çift,45 beşin katı; ikisi de 3’ün katıdır.');
M(55,'On bire bölünen palindrom adayı','Bölünebilme',21,'ABB ve BAB için 11’in almaşık toplam kuralını kullanıp 12 koşulunun gerektirdiği çift son iki basamağı sınar.',['ABB’de 11 testi A − B + B = A olduğundan sayı 11’e bölünemez.','BAB’de test 2B−A; ABB’nin 12’ye bölünmesi için BB = 11B,4’e bölünmelidir.'],['Bu yüzden BAB 11’e, ABB 12’ye bölünür; B = 4 veya 8.','B = 4 için A = 8 olur ama 8443’e bölünmez. B = 8 için 2B−A = 11’den A = 5; 58812’ye,85811’e bölünür. Toplam 13, E.'],'11 kuralını rakam toplamı kuralı sanmak veya hangi sayının hangi böleni sağlayacağını kontrol etmeden atamak.','İki bölünebilme testi','11 kuralı rakamları doğrusal ilişkilendirir; 12’nin 3 ve 4 şartları kalan adayları eler.','858’in 11’e bölünme testindeki almaşık toplam nedir?',['0','3','8','11','21'],3,'8 − 5 + 8 = 11; 11’in katı olduğundan 85811’e tam bölünür.');
M(56,'İki makinenin farklı periyotları','Periyodik problemler',25,'Dört kartonluk kesim çevrimiyle üç kartonluk beden çevrimini aynı sıra numarasında ayrı ayrı değerlendirir.',['Kesim deseni normal, normal, dar, dar biçiminde 4 periyotludur.','Beden deseni S, M, L biçiminde 3 periyotludur; kalan 0 son sırayı temsil eder.'],['175 = 4 × 43 + 3 olduğundan üçüncü desen konumu dar kesimdir.','175 = 3 × 58 + 1 olduğundan birinci beden S dir. Etiket dar–S; A. İki makinenin sıraları birbirini sıfırlamaz.'],'175’i doğrudan 3’e veya 4’e yuvarlamak; her çevrimin kendi kalanı kullanılmalıdır.','EKOK ve ortak çevrim','Birleşik etiket 12 kartonda tekrar eder; 175’in 12 ile kalanı 7’de aynı dar–S sonucunu verir.','Aynı iki desenle 20. kartonun etiketi nedir?',['Normal–S','Normal–M','Dar–S','Dar–M','Dar–L'],3,'20 mod 4 = 0 dar; 20 mod 3 = 2 M.');
M(57,'Rakamlar arasında kat zinciri','Bölünebilme',19,'A’nın B’nin, B’nin C’nin farklı rakam katı olması koşulunu 3’e bölünebilme ile birleştirir.',['Üç basamaklı ABC’de A > 0; farklı ve sıfırsız kat zincirinde A > B > C > 0’dur.','3’e bölünmek için A + B + C,3’ün katıdır.'],['1–9 içindeki kat zincirleri 421,621,631,842,841,821,931 gibi dar adaylardır.','Rakam toplamı 3’ün katı olan uygun zincir 621’dir; 6 + 2 + 1 = 9. Rakam çarpımı 6 × 2 × 1 = 12; B.'],'Kat sözcüğünü yalnız iki kat anlamında almak veya rakamlar farklılığını unutup eşit rakamları kabul etmek.','Bölünebilme zinciri','Çarpan ilişkileri büyüklük sırasını da sağlar; küçük C’den başlayarak sonlu adayları sistematik üretmek mümkündür.','A = 3B, B = 2C ve rakamlar sıfırsızsa en küçük C için ABC kaçtır?',['321','421','621','632','842'],2,'C = 1, B = 2, A = 6; sayı 621 olur.');
M(58,'İlk bilginin yetersiz olması da veridir','Çarpanlar',22,'Toplam 11 koşuluna uyan çiftlerden, çarpımı 1–10 arasında başka çiftle de oluşabilenleri ayırır.',['Toplam 11 çiftleri(1,10),(2,9),(3,8),(4,7),(5,6) dır.','İlk çarpım bilgisi tek çözüm verseydi ikinci bilgiye ihtiyaç kalmazdı.'],['Çarpımlar 10,18,24,28,30.10 = 2·5,18 = 3·6,24 = 4·6,30 = 3·10 alternatiflerine sahiptir.','28 yalnız 4·7 ile oluşur; bu çift ilk anda bilinirdi. Dolayısıyla fark 3 olamaz; B.'],'Yalnız toplam 11’i kullanıp tüm farkları mümkün saymak; konuşmanın ilk belirsizlik cümlesi aday eler.','Bilgi durumuyla eleme','Bir gözlemcinin neyi bilip bilmediği, sayısal değerler kadar kısıt taşıyabilir.','1–10 arasındaki iki farklı sayının çarpımı 35 ise toplam bilgisi olmadan çift belirlenir mi?',['Hayır','Yalnız toplam verilirse','Evet,5 ve 7','Evet,1 ve 35','İki çift vardır'],2,'Bu aralıkta 35’in tek farklı çarpan çifti 5 ve 7’dir.');
M(59,'Beş ve dokuzdan eşit kalan','Kalanlı bölme',18,'A34B’nin 5 ile kalanını son rakamdan,9 ile kalanını rakam toplamından bularak aynı kalan koşulunu iki dala ayırır.',['5 ile bölüm kalanı r = B mod 5’tir.','9 ile bölüm kalanı(A + 7 + B) mod 9’dur; r0–4 arasında kalır.'],['B < 5 ise B − r = 0; A + 7,9’un katı olmalı, A = 2.','B ≥ 5 ise B − r = 5; A + 12,9’un katı olmalı, A = 6. Farklı A değerleri toplamı 8; A.'],'İki kalanı eşitlerken rakam toplamını kalanın kendisi sanmak; önce 9’un katı farkı çıkarılır.','Durumlara ayırma','Birler rakamının 5’in altında veya üstünde oluşu tek farklı taşımayı belirler; on ayrı B denemeye gerek kalmaz.','A34B’de B = 2 ve iki kalan eşitse A kaçtır?',['1','2','3','6','8'],1,'5 kalanı 2; 9 kalanı da 2 için A + 9≡2 mod 9, A = 2.');
M(60,'Bölüm ve kalanı değiştirmek','Kalanlı bölme',18,'Yeni tanımdaki n değişimli sayıyı 9 tabanındaki bölüm–kalan çiftini ters çevirerek kurar.',['49 = 9·5 + 4 olduğundan bölüm 5, kalan 4’tür.','Diğer sayıda bölüm 4, kalan 5 olmalıdır; kalan 5 < 9 koşulu sağlanır.'],['m = 9·4 + 5 = 41 yazılır.','41’in 9 ile bölümü 4 kalanı 5’tir; bunlar 49’un kalanı ve bölümüdür. m = 41, E. Sayının rakamlarını ters çevirmek aynı işlem değildir.'],'49 u94 yapmak veya kalan yerine 9’dan büyük bir değer yazmak; kalan daima bölenin altındadır.','Taban gösterimi','Bölüm ve kalan iki basamaklı 9 tabanlı gösterim gibi düşünülebilir; değişim bu katsayıların yer değiştirmesidir.','17 ile m,5 değişimli. m kaçtır?',['11','12','13','14','15'],2,'17 = 5·3 + 2; bölüm ve kalan yer değişince m = 5·2 + 3 = 13’tür.');
M(61,'Yan yana çokgenlerde ortak kenarlar','Doğrusal denklem',31,'Yeni tanımdaki gensayıyı çokgen sayısıyla ilişkilendirirken ortak kenarın iki kez sayılmasını bir kez düzelterek formül kurdurur.',['n tane k kenarlı çokgende başlangıç sayım nk dır.','Zincirde n − 1 ortak kenar vardır; her biri iki çokgende sayıldığı için birleşik farklı kenar sayısından bir kez çıkarılır.'],['Gensayı nk − (n − 1) = n(k − 1) + 1’dir. 100 için n(k − 1) = 99.','Verilen 3,4,5,6,8 kenarlı türlerde yalnız k = 4 için k − 1 = 3,99’u böler; n = 33, B.'],'Ortak kenarları tamamen yok saymak; tanım ortak kenarı da bir kenar olarak sayar.','Sayma ve bölünebilme','Geometrik zincir doğrusal formüle çevrilince mümkün olma şartı bir tamsayı bölünebilme testine dönüşür.','Dört eş beşgen zincirinin gensayısı kaçtır?',['16','17','18','19','20'],1,'4 × 5 − 3 = 17; eşdeğer formül 4(5 − 1) + 1’dir.');
M(62,'Yanlış ondalık sıralamayı ters okumak','Ondalık sıralama',27,'Onda birleri önce karşılaştıran hatalı sıralamadan rakamların gerçek sırasını çıkarıp birler basamaklarıyla doğru sıralamayı kurar.',['K = a, b; L = b, c; M = c, a dır.','Farklı birler basamaklı pozitif ondalıklarda önce birler rakamı karşılaştırılır.'],['Hatalı K < L < M sırası onda birlere göre b < c < a demektir.','Doğru karşılaştırmada L’nin birleri b en küçük, M’nin c orta, K’nin a en büyüktür; L < M < K, C. Ondalık kuyruklar sonucu ters çeviremez.'],'Yanlış verilen sıralamayı doğrudan doğru saymak veya aynı yanlış önceliği ikinci kez uygulamak.','Hata modelinden çıkarım','Hatanın nasıl yapıldığı bilindiğinde yanlış sonuç da rakamların ilişkisi hakkında güvenilir veri taşır.','a < b < c ise a, c; b, a; c, b sayılarının küçükten büyüğe sırası nedir?',['c, b < b, a < a, c','b, a < a, c < c, b','a, c < b, a < c, b','a, c < c, b < b, a','Eşit'],2,'Birler basamakları farklı olduğundan sıra a, b, c önceliğiyle belirlenir.');
M(63,'Cetvelin sıfır dışındaki payları','Uzunluk denklemi',31,'Cetvellerin fiziksel boyuna iki uçtaki boşlukları ekleyip alttaki ikinci cetvelin sıfır noktasından gerçek hizayı ölçer.',['Üst cetvelin toplam boyu 10 + 0,8 + 0,8 = 11,6 cm dir.','Alttaki her cetvel 6 + 0,2 + 0,2 = 6,4 cm fiziksel uzunluktadır.'],['İkinci alt cetvelin 0 işareti ortak soldan 6,4 + 0,2 = 6,6 cm dedir.','Üst sağ kenarı 11,6 cm olduğundan alt ölçek değeri 11,6 − 6,6 = 5 cm; D.'],'Cetvel üzerinde 10 yazmasını fiziksel toplam boy 10 cm sanmak; başlangıç ve bitiş payları ölçüme dahildir.','Koordinat farkı','Bütün kenarları ortak bir sol başlangıca göre konumlandırıp iki konumu çıkarmak farklı sıfırları yönetir.','Toplam boyu 12 cm üst çubuğun sağ kenarı, altta sıfırı 7 cm deki cetvelde kaçla hizalanır?',['3','4','5','6','7'],2,'Ortak başlangıca göre 12 − 7 = 5 cm.');
M(64,'Terazide aktarılan kütleyi iki kez hesaba katmak','Denklem kurma',31,'Bir kefeye ekleme ve oradan diğerine aktarma sırasında farkın iki yönde değişmesini modelletir.',['Başlangıçta iki kefe 45 g ile dengededir.','B’ye x eklenip y kütle A’ya taşınırsa A kefesi 45 + y, B kefesi 45 + x − y olur.'],['Denge 45 + y = 45 + x − y; x = 2y gerektirir.','B deki 20 veya 25 g taşınabilir; eklenen seçeneklerde 40 = 2 × 20 vardır,50 yoktur. Eklenen 40 g; E.'],'Aktarılan y yi yalnız B’den çıkarmak; aynı anda A’ya eklenmesi denge farkını 2y değiştirir.','Korunan toplam ve değişen fark','Aktarma toplam kütleyi değiştirmez ama iki taraf farkını iki kat aktarılan miktar kadar değiştirir.','Dengeli kefelerden B’ye 30 g ekleniyor. B’den A’ya kaç g aktarılırsa yeniden denge olur?',['10','15','20','25','30'],1,'Fark 30 g; bir gram aktarma farkı 2 g azaltır,15 g yeterlidir.');
M(65,'Sıcaklık artışı aralığını mutlak değerle yazmak','Mutlak değer',36,'Başlangıç 5 °C’ye 6–10 derece artışı ekleyip oluşan 11–15 aralığını merkez–yarıçap biçimine dönüştürür.',['Yeni sıcaklık başlangıçla artışın toplamıdır.','[L, U] aralığı |x − (L + U)/2| ≤ (U − L)/2 biçiminde yazılır.'],['Pazartesi sıcaklığı 5 + 6 = 11 ile 5 + 10 = 15 arasındadır.','Orta değer 13, yarı genişlik 2; |x − 13| ≤ 2, A. 6 ve 10 doğrudan son sıcaklık değildir.'],'Artış aralığını sıcaklık aralığı diye almak veya merkez olarak başlangıç 5’i kullanmak.','Aralık dönüşümü','Sözel alt–üst sınırlar önce x eşitsizliğine, sonra merkezden uzaklık tanımına çevrilir.','Başlangıç 8 derece, artış 3–7 dereceyse son sıcaklık hangi mutlak değer aralığındadır?',['|x − 5| ≤ 2','|x − 11| ≤ 4','|x − 13| ≤ 2','|x − 15| ≤ 2','|x − 8| ≤ 7'],2,'Son değer 11–15; merkezi 13, yarı genişliği 2’dir.');
M(66,'Sileceğin temizlediği halkasal sektör','Alan denklemi',31,'İç yarıçap 1 ve dış yarıçap 5 olan 120° halkasal sektörün alanını yarım camın alanının yarısına eşitler.',['Halkasal tam alanπ(5² − 1²) = 24π dir.','120° tam çemberin üçte biri; cam yarım daire olduğundan yarısının alanıπR²/4’tür.'],['Temizlenen alan 24π/3 = 8π.','8π = πR²/4’den R² = 32, R = 4√2; A. Silecek 1 birimlik merkez bölgesini temizlemez.'],'Sektörü doğrudan 25π/3 almak veya yarım dairenin yarısını yine yarım daire sanmak.','Geometriden denkleme','Temizlenen ve toplam alan farklı şekillerde verilir; aynı büyüklük oldukları için tek bilinmeyenli alan eşitliği kurulur.','İç ve dış yarıçapları 2,4 olan 90° halkasal sektörün alanı kaçπ dir?',['2','3','4','6','12'],1,'(4² − 2²)π/4 = 12π/4 = 3π.');
M(67,'Aynı sütü iki kap türüyle ölçmek','Denklem sistemi',33,'Eşit şişe miktarını 3 bardak + 1 fincan ve 2 bardak + 3 fincan olarak eşitleyip bir bardak–fincan oranı buldurur.',['Aynı dolu şişelerin hacimleri eşittir.','Özdeş kaplar tamamen dolduğundan kap sayısıyla kap hacmi çarpılır.'],['Bardak b, fincan f:3b + f = 2b + 3f, buradan b = 2f.','Bir şişe 3·2f + f = 7f içerir. Üçüncü şişe 7 fincan doldurur; B. Şişe sayısı değişse de aynı hacim bilgisi korunur.'],'Şekillerdeki toplam kap sayısını eşitlemek; bardakla fincanın kapasiteleri farklıdır.','Eşit hacim modeli','Bilinmeyen şişe hacmini iki ifadeyi eşitleyerek yok etmek, yalnız istenen fincan birimine ulaşmayı sağlar.','Bir şişe 2 bardak + 2 fincan veya 1 bardak + 5 fincan dolduruyor. Şişe kaç fincandır?',['5','6','7','8','9'],3,'2b + 2f = b + 5f den b = 3f; şişe 8f eder.');
M(68,'Sayı doğrusunda iki simetrik nokta','Mutlak değer',36,'Sıfıra uzaklığı A/2 olan iki noktanın A’ya uzaklıklarını ayrı yazarak iki mümkün A değerini toplatır.',['0’a uzaklığı A/2 olan sayılar + A/2 ve − A/2’dir.','A pozitif olduğundan bu iki noktanın A’ya uzaklıkları A/2 ve 3A/2’dir.'],['A/2 = 6 ise A = 12.','3A/2 = 6 ise A = 4. Olası A değerlerinin toplamı 16; B. İşaretlenen negatif nokta göz ardı edilemez.'],'Sıfıra uzaklık koşulundan yalnız pozitif noktayı almak veya A’ya uzaklıkla 0’a uzaklığı aynı sanmak.','Mutlak değer dalları','Uzaklık eşitliği işaretten bağımsız iki konum üretir; hedef noktaya uzaklıklar farklı denklemler verebilir.','Pozitif A için±A/3 noktalarından birinin A’ya uzaklığı 8. A değerleri toplamı kaçtır?',['12','15','18','20','24'],2,'Uzaklıklar 2A/3 ve 4A/3; A = 12 veya A = 6, toplam 18.');
M(69,'Dairesel program düğmesindeki açık boşluk','Periyodik açı',25,'Ardışık programlar arasındaki eş açıyı,7’den 1’e geçen büyük çevresel boşluğun 150° bilgisiyle hesaplatır.',['1–8 arasındaki yedi ardışık aralık eşittir; 8’den 1’e kalan boşluk aynı olmak zorunda değildir.','7’den 1’e saat yönünde gidilen yol,1’den 7’ye altı küçük aralığın 360° ye tümleyenidir.'],['360 − 6d = 150; d = 35°.','1’den saat yönünün tersine 140° = 4d dönmek dört program ilerletir:1→2→3→4→5. Son program 5; C.'],'Sekiz programı tam çembere eşit bölüp 45° almak; çizim ve verilen 150° bunu sağlamaz.','Çevrimde tamamlayıcı açı','Doğrudan verilen dönüş küçük aralıkların ters yönündedir; tam açıdan çıkarma ortak birim açıyı buldurur.','Ardışık program açısı 30°.1’den ters saat yönünde 90° dönülürse hangi programa gelinir?',['2','3','4','5','6'],2,'Üç aralık ilerlenir; 1’den 4’e ulaşılır.');
M(70,'Yarım daire çevresi ve alan ölçeği','Oran orantı',45,'Çevreleyen ipin yayla çapı birlikte içerdiğini yazıp çevre oranından yarıçap ve ardından alan oranı çıkarır.',['Yarım dairenin çevresiπR+2R = (π + 2)R dir.','Benzer şekillerde uzunluk oranının karesi alan oranıdır.'],['Büyük yarım daireyi saran ipin üçte biri küçük yarım daireyi sarar; (π + 2)R = 3(π + 2)r.','R = 3r; alan oranı R²/r² = 9, E. Alanın yarım olması iki tarafta sadeleşir.'],'İp üçe ayrıldığı için alan oranını 3 saymak veya yarım daire çevresinde çapı unutmak.','Benzerlik ölçeği','Çevre ve alan aynı ölçekte büyümez; doğrusal katsayı ikinci boyutta karesini verir.','Benzer iki yarım dairenin çevre oranı 5/2 ise alan oranı nedir?',['5/2','5','10','25/4','25/2'],3,'Yarıçap oranı 5/2; alan oranı bunun karesi 25/4’tür.');
M(71,'Ağaç büyürken iki mutlak fark','Mutlak değer denklemi',38,'Bina yüksekliği sabitken ağacın iki katına çıkmasından önce ve sonra hangi cismin uzun olduğunu varsaymadan iki fark koşulunu çözer.',['İlk koşul|B − T| = 8, ikinci|B−2T| = 3’tür.','Bina ve ağacın yükseklikleri pozitiftir; negatif çözümler fiziksel değildir.'],['B = T + 8 dalında T + 8 = 2T±3; T = 5 veya T = 11; B = 13 veya B = 19.','B = T − 8 dalı pozitif T vermez. Olası binalar 13 ve 19 metre; I ve III, C. 16 koşulları sağlamaz.'],'Binanın her iki zamanda da ağaçtan uzun kaldığını peşinen kabul etmek; büyüyen ağaç binayı geçebilir.','İşaret dalları','Mutlak fark yön bilgisi taşımaz; iki eşitlikteki olası işaretlerin pozitiflik altında denetlenmesi gerekir.','Bina 12 m, ağaç başlangıç 7 m. Ağaç iki katına çıkınca yükseklik farkı kaç m olur?',['1','2','3','5','7'],1,'Yeni ağaç 14 m; fark|12 − 14| = 2 m.');
M(72,'En az banknotla üç çekim','Doğal sayılarda işlemler',10,'Verilen 5,10,20,50,100 TL lik banknotlarla her tutarın minimum parça sayısını bulup tutar sırasından bağımsız karşılaştırır.',['Büyük banknotları kullanmak bu değer sisteminde minimum parça sayısını sağlar.','Kalan tutar da aynı yöntemle mevcut banknotlara ayrılır.'],['495 = 4·100 + 50 + 2·20 + 5, sekiz banknot; 265 = 2·100 + 50 + 10 + 5, beş banknot.','550 = 5·100 + 50, altı banknot. PB < PC < PA; D. Büyük tutar daha az banknot gerektirebilir.'],'Tutarların büyüklük sırasını banknot sayısı sırası sanmak veya 20 TL lik banknotu atlamak.','Ayrık optimizasyon','Amaç para toplamını değil parça sayısını en aza indirmektir; sayıların değerleri ve izinli banknotlar belirleyicidir.','Aynı banknotlarla 285 TL en az kaç banknotla verilir?',['4','5','6','7','8'],2,'100 + 100 + 50 + 20 + 10 + 5 altı banknottur.');
M(73,'Sayı doğrusunda simetri ve çarpım','Eşitsizlikler',32,'K’nin 1’e ve L’nin 2’ye eş uzaklığından L = 3 − K ilişkisini kurup çarpımın yerini sıralama ile sınırlar.',['Şekilde 1 < K < L < 2’dir.','K − 1 = 2 − L koşulu K + L = 3 demektir.'],['K = 1 + t, L = 2 − t; 0 < t < 1/2. Çarpım 2 + t − t² > 2 ve en fazla 9/4’tür.','A, B, C noktaları 2’nin solunda, E ise 3’ün sağındadır; 2 ile 3 arasındaki D mümkün adaydır. D.'],'K ve L’yi şekildeki yaklaşık piksel konumlarından kesin ondalıklar sanmak; önemli olan sıra ve verilen eş uzaklıktır.','Simetrik toplam','Sabit toplamda çarpım orta noktaya yaklaştıkça artar; cebirsel ifade uygun aralığı belirler.','K = 1,2 ve K + L = 3 ise K·L kaçtır?',['1,44','1,8','2','2,16','2,4'],3,'L = 1,8; 1,2 × 1,8 = 2,16.');
M(74,'Kalori eşiğini ortak toplamdan çıkarmak','Eşitsizlikler',32,'İki seçenek toplamlarının gerekli kaloriyle ilişkisini, eşit olan çorba + salata toplamını referans alarak tek porsiyon sırasına çevirir.',['Gereken kalori Ç + S dir.','Aynı sayı eşitsizliğin iki yanından çıkarılabilir; eşitsizlik yönü değişmez.'],['Ç + M > Ç + S olduğundan M > S.','M + S ≤ Ç + S olduğundan M ≤ Ç. Birleştirince S < M ≤ Ç; D. Meyve–salata seçiminde aşmamak eşitliği de kapsar.'],'Aşmadı ifadesini kesin küçüktür diye okumak veya toplamların sırasını tek tek porsiyonlara geçirmeden tahmin etmek.','Ortak terimi eleme','Aynı besin iki toplamda da bulunduğunda katkısı çıkarılır ve kalan iki besinin doğrudan karşılaştırması elde edilir.','A + B = 100, A + C > 100, B + C ≤ 100 ise doğru sıra nedir?',['A < B < C','B < C ≤ A','C < B < A','A ≤ C < B','Üçü eşit'],1,'İlk eşitlikten diğerlerini çıkarınca C > B ve C ≤ A bulunur.');
M(75,'Düşülen mesafeden yerden yüksekliğe','Mutlak değer',36,'800 metreden 400–500 metre düşme koşulunu kalan yükseklik 300–400 olarak ters yönde dönüştürüp mutlak değer biçimini yazar.',['Yerden yükseklik başlangıç yüksekliği eksi düşülen mesafedir.','Kapalı[a, b] aralığının merkezi(a + b)/2, yarı genişliği(b − a)/2’dir.'],['En çok 500 m düşünce yükseklik 300; en az 400 m düşünce 400 m.','300 ≤ x ≤ 400, merkez 350 ve yarı genişlik 50; |x − 350| ≤ 50, A.'],'400–500 aralığını doğrudan yerden yükseklik sanmak veya 800’den çıkarırken sınırların sırasını aynı bırakmak.','Azalan dönüşüm','x = 800 − d fonksiyonu azalandır; d nin büyük ucu x in küçük ucuna karşılık gelir.','1000 m den 600–700 m düşülüyorsa kalan yükseklik hangi aralıktadır?',['100–200','200–300','300–400','400–500','600–700'],2,'1000 − 700 = 300,1000 − 600 = 400; aralık 300–400.');
M(76,'Eşitsizlik bölgesinden katsayı işaretleri','Doğrusal eşitsizlik',34,'Aşağı doğru açılan çözüm kamasında her eşitsizliğin y ye göre yönünü ve doğrunun eğim–kesişim işaretini birlikte yorumlar.',['x + ay = b doğrusunun eğimi − 1/a, y kesimi b/a dır.','Bir eşitsizlik negatif katsayıya bölününce yön değişir.'],['x + ay ≤ b nin alt yarı düzlem olması a > 0 gerektirir; çizgi azalan ve y kesimi negatif olduğundan b < 0.','x + cy ≥ d nin alt bölge vermesi c < 0; artan çizginin y kesimi pozitif olduğundan d < 0. Sıra+,−,−,−; A.'],'Yalnız doğru eğimine bakıp eşitsizliğin taralı tarafını kullanmamak; hangi doğru hangi eşitsizliğe ait olduğu bölgeyle belirlenir.','Grafik–cebir dönüşümü','Eğim katsayısı ve yarı düzlem yönü birlikte okununca isimsiz iki sınır doğru uygun eşitsizliklerle eşleşir.','x − 2y ≥ 4 eşitsizliğinin y biçimi nedir?',['y ≥ x/2 − 2','y ≤ x/2 − 2','y ≤ 2x − 4','y ≥ 2x − 4','y = x/2 + 2'],1,'−2y ≥ 4 − x ifadesi − 2’ye bölününce y ≤ x/2 − 2 olur.');
M(77,'İçecek bileşenlerinin fiyatı','Denklem sistemi',33,'100 mL lik kahve, su, süt birimlerini üç içecekten belirleyip yeni bileşimin fiyatını hesaplatır.',['Bileşen miktarları 100 mL birimleriyle sayılır; toplam fiyat bileşen fiyatlarının toplamıdır.','K+3S = 9,3K+S = 15, K+3M = 12 denklemleri şekilden okunur.'],['İlk iki denklemden K = 4,5 TL ve S = 1,5 TL. Üçüncüden M = 2,5 TL.','İstenen 2K+S + M = 9 + 1,5 + 2,5 = 13 TL; E. 400 mL ortak hacim bileşimlerin aynı olduğu anlamına gelmez.'],'Kahve sayısını tüm içeceklerde 1 kabul etmek veya sütlü içecekteki üç süt katmanını atlamak.','Karışımın doğrusal maliyeti','Toplam fiyatın bileşen miktarlarına doğrusal bağlı olması denklem sistemini mümkün kılar.','100 mL kahve 4, su 1, süt 3 TL ise 200 mL kahve + 100 su + 100 süt kaç TL?',['9','10','11','12','13'],3,'2 × 4 + 1 + 3 = 12 TL.');
M(78,'İki ürün de uygun aralığın dışında','Mutlak değer eşitsizliği',38,'A ve B ürünlerinin ayrı saklama aralıklarını açıp ikisinin aynı sıcaklıkta bozulması için her iki aralığın dışında kalmayı arar.',['|SA + 1| < 5 koşulu − 6 < SA < 4 verir.','|SB − 13| < 7 koşulu 6 < SB < 20 verir; uçlar uygun aralığa dahil değildir.'],['−1,0,3 A için uygundur; 7 B için uygundur.','5 ne(−6,4) ne(6,20) içindedir; iki ürün de bozulur, D. İkisine ortak uygun sıcaklık aranmadığına dikkat edilir.'],'İki aralığın kesişimini bulup boş olduğu için tüm seçenekleri doğru sanmak; bozulma her ürünün kendi koşulunun tersidir.','Mantıksal değil','Her ikisinin bozulması, uygun aralıkların birleşiminin dışında kalmak demektir.','A için 0 < x < 4, B için 6 < x < 10 uygun. Hangisinde ikisi de uygun değildir?',['1','3','5','7','9'],2,'5 her iki açık aralığın da dışındadır.');
M(79,'Saat farklarında dört olasılık','Mutlak değer',36,'A–B farkı 4, B–C farkı 3 iken iki yönlü farkları ayrı dallara ayırarak C’nin olamayacağı saati buldurur.',['Saat farkı yön belirtmediği için B = A±4’tür.','İkinci fark da C = B±3; toplam kayma±4±3 olabilir.'],['A saati 14.00 iken B saati 10.00 veya 18.00 olur. B = 10.00 için C = 07.00 veya 13.00; B = 18.00 için C = 15.00 veya 21.00.','Olası C saatleri 07,13,15,21; 17 oluşmaz, D. Bu saatlerde gün dönümü gerekmemektedir.'],'Saat farklarını yalnız toplamak veya yalnız çıkarmak; iki kentten hangisinin ileride olduğu belirtilmemiştir.','İşaret kombinasyonları','İki belirsiz yönlü fark dört aday üretir; sonlu dal tablosu hiçbir olasılığı atlamaz.','A saati 12, A–B farkı 5, B–C farkı 2. C hangisi olamaz?',['5','9','15','19','17'],4,'Adaylar 12±5±2 = 5,9,15,19; 17 mümkün değildir.');
M(80,'Ortak negatif çarpanla sıra terslenir','Basit eşitsizlikler',32,'a > ab > 2a > ac zincirinin a yı negatif zorladığını bulup bölme sırasında bütün yönleri ters çevirir.',['Zincirde a > 2a olduğu için a < 0’dır.','Negatif a ya bölmek eşitsizlik yönlerini ters çevirir.'],['a ya bölünce 1 < b < 2 < c elde edilir.','Dolayısıyla a0’ın solunda, b1 ile 2 arasında, c2’nin sağındadır. Bu düzen A seçeneğidir. a = 0 zincirde kesin eşitsizlikleri sağlayamaz.'],'a ya işaretini belirlemeden bölmek veya negatif bölmede yalnız ilk eşitsizliğin yönünü çevirmek.','İşaret belirleme','Ortak çarpanlı zincirde önce aynı değişkenin iki katıyla karşılaştırılması güvenli bölme yönünü belirler.','a < 0 ve ab > 3a ise b için hangi ilişki doğrudur?',['b > 3','b < 3','b = 3','b > 0 kesin','b < 0 kesin'],1,'Her iki yanı negatif a ya bölünce yön ters döner, b < 3 olur.');
M(81,'En yakın ve en uzak tahmin','Mutlak değer eşitsizliği',38,'27,35,39 tahminlerine uzaklıkları karşılaştırırken tahminlerin orta noktalarının eşit hata sınırı oluşturmasını kullanır.',['35 e27’den yakın olmak sayfa sayısını 31’in üstüne taşır.','39’un 27’den daha uzak olması sayfa sayısını 33’ün altına sınırlar; eşit hatalar yasaktır.'],['Burcu en yakın olduğundan N > 31; Can en uzak olduğundan N < 33.','Tam sayı sayfa sayısı yalnız 32’dir; hata büyüklükleri 5,3,7 olur. Rakam toplamı 3 + 2 = 5, B.'],'Sayfa sayısını doğrudan 35 seçmek veya eşit uzaklıktaki 31 ve 33 sınırlarını dahil etmek.','Orta nokta eşiği','İki sabit sayıya eşit uzak noktası ortalamalarıdır; yakınlık karşılaştırması bu eşiklerle doğrusal aralığa dönüşür.','20 ve 30 tahminlerinden 30’a daha yakın doğal N için hangisi olamaz?',['25','26','27','28','29'],0,'25 iki tahmine eşit uzaklıktadır; daha yakın olması için N > 25 gerekir.');
M(82,'İki satış fiyatından maliyet aralığı','Kâr zarar',52,'Takımın toplam maliyetini kurup bir fiyatın kâr, diğerinin zarar oluşturmasını buzdolabı maliyetine iki sınır olarak uygular.',['Toplam maliyet 40000 + b TL dir.','Kârda satış maliyetten büyük, zararda küçüktür; eşitlik iki koşulda da yoktur.'],['2b + 30000 > 40000 + b den b > 10000.','3b − 20000 < 40000 + b den b < 30000. Dolayısıyla 10000 < b < 30000, |b − 20000| < 10000; A.'],'Yalnız buzdolabını maliyet sayıp 18000 ve 22000 TL lik ürünleri atlamak veya kâr koşulunu eşitlik yazmak.','Çift sınır','İki farklı satış senaryosu aynı bilinmeyeni alt ve üstten sınırlar; kesişim mutlak değerin merkez–yarıçap biçimine çevrilir.','Maliyeti 20 + x olan takım 2x + 10’a kârla satılıyorsa x için ne gerekir?',['x < 10','x = 10','x > 10','x < 20','x = 20'],2,'2x + 10 > 20 + x eşitsizliği x > 10 verir.');
M(83,'Yeni sembolde işlem sırası','Tanımlı işlemler',10,'Üç parçalı dairesel sembolde üstteki sayının alt ikilinin toplamıyla çarpılmasını doğru uygulayıp pozitif kökü seçer.',['Sembolün değeri a(b + c) dir.','Bütün x ler aynı pozitif gerçek sayıyı gösterir; x(x + x) = 2x² olur.'],['Sol değer 8(7 + 6) − 6(5 + 4) = 104 − 54 = 50.','Sağ değer 2x²; 2x² = 50’den x² = 25 ve x > 0 nedeniyle x = 5, E. Negatif kök tanıma aykırıdır.'],'Dağıtmayı a·b + c şeklinde yapmak veya yalnız bir alt x i sayarak x² yazmak.','Karesel denklemde alan kısıtı','Cebir iki kök üretebilir; başlangıçtaki pozitiflik varsayımı fiziksel/sayısal uygun çözümü seçer.','Aynı sembolde bütün bölmeler x ve değer 72 ise pozitif x kaçtır?',['3','4','5','6','8'],3,'x(x + x) = 2x² = 72; x² = 36, pozitif x = 6.');
M(84,'Şerit değişimlerinde net araç akışı','Denklem kurma',33,'Her şerit için girenleri ekleyip çıkanları çıkarır; son sayıların eşitliğinden başlangıç sayılarını sıralar.',['Şerit değişimi toplam araç sayısını korur.','Her şeridin son sayısı başlangıç + giren − çıkan biçimindedir.'],['A son = a − 5 + 4 = a − 1; B son = b + 5 − 4 − 1 + 3 = b + 3; C son = c + 1 − 3 = c − 2.','Ortak son sayı k ise a = k + 1, b = k − 3, c = k + 2. Başlangıçta b < a < c; C.'],'Tek yönlü hareketleri sayıp karşı yönde dönenleri unutmak veya başlangıç sayılarının zaten eşit olduğunu varsaymak.','Akış bilançosu','Bir ağ düğümündeki stok değişimi net akışa eşittir; şeritler arası hareket bu genel ilkenin ayrık örneğidir.','A’dan B’ye 7, B’den A’ya 2 araç geçince son sayılar eşit. Başta A, B’den kaç fazla?',['2','5','7','10','14'],3,'A’daki sayı 5 azalır, B’deki sayı 5 artar; eşitlenmek için başlangıç farkı 10 olmalıdır.');
M(85,'Beraberlik ve devre gol farkı','Mutlak değer',38,'Maç sonu eşit gol sayısını n ile ifade edip ikinci devre toplamını birinci devreden ayırarak tam sayı kısıtını sınar.',['Birinci devre toplamı 3; maç sonu her takım n ise toplam 2n dir.','İkinci devre toplamı 2n − 3; devre farkı|3 − (2n − 3)| = |6 − 2n| olur.'],['|x − 4| < 3 koşulu 1 < x < 7; x çift olduğundan 2,4,6 olabilir.','n = 3 için x = 0 olduğundan koşul bozulur. n = 2,4,5,6 uygundur; A’nın toplamı 3 olamaz, B.'],'Fark x i doğrudan takım golleri farkı sanmak; x iki devredeki toplam goller arasındaki farktır.','İç içe mutlak değer','Önce bağlamdaki fark tanımlanır, sonra verilen eşitsizliğe yerleştirilir; değişkenlerin anlamı karıştırılmaz.','İlk devre toplam 4, maç toplam 10 gol. İki devredeki toplamların farkı kaçtır?',['0','1','2','4','6'],2,'İkinci devre 6 gol; fark|6 − 4| = 2.');
M(86,'Kasiyerin iki ürün fiyatını değiştirmesi','Denklem sistemi',33,'Doğru alışverişle yanlış hesap arasındaki 4 TL farkını, roka ve tere miktarlarının 1 ile 3 olmasına göre modelletir.',['Maydanozun toplamı 2 × 15 = 30 TL dir.','Doğru hesap 104, ödenen yanlış hesap 100 TL olduğundan iki ayrı doğrusal denklem kurulur.'],['R+3T+30 = 104;3R+T + 30 = 100, yani R+3T = 74 ve 3R+T = 70.','İkinci denklemden veya eliminasyonla T = 19, R = 17 bulunur. Terenin demeti 19 TL; B.'],'4 TL’yi tek bir demetin fiyat farkı saymak; yer değiştiren adetler nedeniyle toplam hata 2(T − R) dir.','Hata farkı','İki hesap çıkarılırsa 2(T − R) = 4 doğrudan fiyat farkını verir; toplam denklem mutlak fiyatları tamamlar.','Bir üründen 1, diğerinden 3 alınıyor. Fiyatlar yer değişince toplam 6 TL düşüyorsa pahalı–ucuz farkı kaç TL?',['2','3','4','6','12'],1,'Toplam fark(3 − 1)(pahalı − ucuz) = 6; birim fark 3 TL.');
M(87,'Alan çarpanlarından kenar sırası','Asal çarpanlar',22,'1’den büyük tamsayı kenarları alanın çarpan çiftlerinden çıkarıp kısa kenar sırasına göre uzun kenarları yeniden eşler.',['46 = 2·23,65 = 5·13,93 = 3·31’dir.','Bu alanlar iki farklı asalın çarpımı olduğundan 1 hariç tek kenar çifti vardır.'],['Kısa kenarlar 2,3,5’tir; k A < kB < k C koşulu A alanını 46, B’yi 93, C’yi 65 yapar.','Uzun kenarlar u A = 23, u B = 31, u C = 13; u C < u A < u B, D. Alan sırası uzun kenar sırasıyla aynı değildir.'],'Dikdörtgen adlarını verilen alanların yazılış sırasıyla eşlemek; metin hangi alanın hangi harfte olduğunu söylemez.','Çarpan eşlemesi','Alan tek başına kenarı belirlemeyebilir; burada tamsayılılık ve asal çarpan yapısı belirsizliği kaldırır.','Alanı 77, iki kenarı 1’den büyük tamsayı dikdörtgenin uzun kenarı kaçtır?',['7','9','10','11','14'],3,'77 = 7·11; izinli tek çiftte uzun kenar 11’dir.');
M(88,'Eksik mutlak değer çizgisinin yeri','Mutlak değer',36,'Açılış çizgisinden farklı son noktalara kadar olan toplamı mutlak değere alıp kalan işlemleri dışarıda sürdürür.',['Mutlak değer yalnız iki çizgi arasındaki ifadeyi kapsar.','Çizginin yeri değişince dışarıda kalan terimlerin işaretleri farklı etki eder.'],['5’in sağına çizgi konursa içerisi − 3 + 4 − 5 = −4, mutlak değeri 4’tür.','Dışarıda + 6 − 7 kalır; 4 + 6 − 7 = 3, C. Diğer sonlandırmalar eşitliğin sağındaki 3’ü sağlamaz.'],'Bütün ifadeyi tek mutlak değer içine almak veya kapanış çizgisinden sonraki terimlerin de işaretini değiştirmek.','İşlem kapsamı','Parantez gibi mutlak değer çizgisi de kapsam belirler; çözüm yalnız sayısal hesap değil doğru gruplanmayı bulmadır.','|−4 + 1|+2 işlemi kaçtır?',['−5','−1','1','3','5'],4,'İç toplam − 3; mutlak değer 3 ve dışarıdaki 2 ile sonuç 5.');
M(89,'Üç sıra tablo arasında ortak boşluk','Denklem sistemi',33,'Eş çevreli karelerin eş kenarlı olduğunu kullanıp duvar genişliğini üç farklı sıra için aynı değişkenlerle ifade eder.',['Kare tabloların eş çevresi eş kenar s demektir.','İkinci ve üçüncü sıradaki komşu tablo boşlukları ortak d dir.'],['Üstten W = 108 + s; ortadan W = 66 + 2s + d, dolayısıyla s + d = 42.','Alttan W = 10 + 3s + 2d + x = 94 + s + x. Üstle eşitlik 108 + s = 94 + s + x; x = 14 cm, D.'],'İkinci sıranın tek boşluğuyla üçüncünün iki boşluğunu aynı toplam sanmak; her aralık ayrı d ekler.','Ortak uzunluğu eleme','s ve d yi tek tek bulmadan s + d ilişkisi alt satıra yerleştirilerek aranan kenar boşluğu bulunur.','W = 80 + s ve W = 50 + 2s + d ise s + d kaçtır?',['20','25','30','40','50'],2,'Eşitleyince 80 + s = 50 + 2s + d; s + d = 30.');
M(90,'Her adımda üçe ayrılan hamur','Üslü ifadeler',39,'Tek başlangıç parçasından her adımda bütün parçaların üçe bölünmesinin doğrusal artış değil üstel çoğalma olduğunu ölçer.',['Her aşamada önceki toplam parça sayısı 3 ile çarpılır.','n adım sonunda bir parçadan 3ⁿ parça oluşur.'],['Dört adımın sayıları 3,9,27,81’dir.','Sonuç 3⁴ = 81; E. İlk örnekteki ikiye bölme ve üç adım bilgisi yalnız yöntemi açıklamak içindir, yeni koşulda kullanılmaz.'],'Dört adımda 3 + 3 + 3 + 3 = 12 saymak veya yalnız yeni eklenen parçaları toplam parça sayısı sanmak.','Geometrik çoğalma','Bir önceki durumdaki her eleman aynı sayıda alt eleman üretiyorsa toplam sabit oranla büyür.','Bir parça her adımda dörde bölünüyor. Üçüncü adım sonunda kaç parça vardır?',['12','16','32','48','64'],4,'4 × 4 × 4 = 4³ = 64 parça.');
M(91,'Kareköklü sayının bulunduğu aralık','Köklü ifadeler',42,'Üst buzdolabı bölmesinin 1,5–2 m aralığını okuyup köklü seçenekleri kareleriyle karşılaştırır.',['Süs üst bölmede olduğundan 1,5 < h < 2’dir.','Pozitif sayılarda kare alma sıralamayı korur; 2,25 < h² < 4 olmalıdır.'],['√2 < 1,5 çünkü 2 < 2,25;√3 ise 2,25 < 3 < 4 aralığındadır.','√5,√6,√7’nin hepsi 2’den büyüktür. Uygun yükseklik√3 m; B. Alt bölüm yüksekliği üst bölümün başlangıcını belirler.'],'Üst bölümün kendi 0,5 m yüksekliğini yerden yükseklik sanmak veya kareköklerin yaklaşık değerlerini yanlış ezberlemek.','Aralıkta kare alma','Pozitif aralığı karesine taşımak irrasyonel seçenekleri hesap makinesi olmadan tam karşılaştırmayı sağlar.','2 < h < 3 ise hangisi olabilir?',['√3','√4','√6','√9','√10'],2,'4 < h² < 9; 6 bu aralıktadır,√6 uygundur.');
M(92,'Her turda kalan oranı çarpmak','Üslü ifadeler ve yüzde',39,'Her turda beşte birin elenmesini kalan 4/5 oranına çevirip altı ardışık turdaki çarpımı başlangıç 10⁶ ile sadeleştirir.',['Her tur katılanların 4/5’i kalır.','Altı turda aynı oran altı kez çarpılır; elenen oranla kalan oran farklıdır.'],['Kalan 10⁶(4/5)⁶ = (10·4/5)⁶ = 8⁶.','8⁶ = (2³)⁶ = 2¹⁸; B. Her turdaki kayıp başlangıç sayısının sabit beşte biri değildir.'],'Her turda 200000 kişi çıkarmak veya kalan oranını 1/5 almak; tur tabanı her defasında değişir.','Oranların bileşkesi','Ardışık yüzdelerde toplam etki oranların çarpımıdır; ortak üsler sadeleştirmeyi kolaylaştırır.','Başlangıç 5⁴ kişi, her tur 4/5’i kalıyor. Dört tur sonunda kaç kişi kalır?',['4','16','64','256','625'],3,'5⁴(4/5)⁴ = 4⁴ = 256.');
M(93,'Boyanmış oranın karekökü','Köklü ifadeler',42,'Şekildeki dokuz pembe kareyi 16’ya oranlayıp bu sayının kareköküne ulaşmak için gereken yeni payı hesaplatır.',['Başlangıç oranı 9/16’dır.','Pozitif kesrin karekökü√9/√16 = 3/4; toplam parça sayısı 16 sabit kalır.'],['Yeni oran 3/4 = 12/16 olmalıdır; pembe sayısı 12’ye çıkmalıdır.','Başlangıçta 9 olduğundan 12 − 9 = 3 yeni parça boyanır; C. Zaten boyalıları yeniden saymak gerekmez.'],'Boyalı sayının karekökünü 3 bulup doğrudan üç boyalı gerektiğini söylemek; karekök oran üzerinde alınır.','Orandan sayıya dönüş','Hedef oran bilindikten sonra sabit toplamla çarpılması hedef renkli kare sayısını verir.','25 karenin 16 sı boyalı. Oranın kareköküne eşit yeni oran için kaç kare daha boyanmalı?',['2','3','4','5','9'],2,'√(16/25) = 4/5 = 20/25; 20 − 16 = 4 kare.');
M(94,'Müdürleri toplamdan unutmamak','Üslü ifadeler',39,'81 ilde 16 müdüre ve her müdürün 35 öğretmenine ulaşılmasını, müdürlerle öğretmenlerin toplamı olarak çarpanlaştırır.',['Müdür sayısı 81 × 16’dır.','Her okulda mesaj alan toplam 1 müdür + 35 öğretmen = 36 kişidir.'],['Toplam 81 × 16 × 36 = 3⁴·2⁴·(2²3²).','Bu 2⁶3⁶ = (2·3)⁶ = 6⁶ eder; C. Yalnız öğretmenleri saymak 35 çarpanını bırakıp yanlış sonuca götürür.'],'81 × 16 × 35 hesaplayıp müdürleri dışlamak veya öğretmen sayısını tüm proje için 35 kabul etmek.','Çarpanları aynı üste toplama','Asal çarpanlarda ortak üsler birleştirilerek seçeneklerdeki tek kuvvet biçimine ulaşılır. Mesaj alan müdür ile öğretmen grupları ayrık olduğundan kişi toplamında aynı kişi iki kez sayılmaz.','9 bölgede 4 okul ve her okulda 1 yönetici + 8 öğretmen var. Toplam kaç kişi?',['108','144','216','324','648'],3,'9 × 4 × 9 = 324 kişi.');
M(95,'Kökleri tam sayı yapacak eşleştirme','Köklü ifadeler',42,'Altı kökü birer kez kullanarak çarpımlarda kare dışına çıkmayan asal çarpanları eşleştirir.',['√u·√v = √(uv); tam sayı için uv tam kare olmalıdır.','Kökler sadeleşince√5,2√2,2√3,3√2,2√5,3√3 olur.'],['Aynı kök türleri eşleşir:√5√20 = 10,√8√18 = 12,√12√27 = 18.','Toplam 10 + 12 + 18 = 40; A. Çiftlerin sırası değişebilir ama toplam değişmez.'],'Kök içlerini toplamak veya yalnız birbirine yakın sayıları eşleştirmek; tam kare çarpım koşulu esas alınır.','Asal üs paritesi','Tam karede her asalın üssü çifttir; kök eşleştirme eksik tek üsleri tamamlamaktır. Örneğin 5 çarpanı taşıyan iki kökün birlikte kullanılması diğer√2 ve√3 çiftlerini de zorunlu bırakır.','√12 ile hangisi çarpılırsa tam sayı olur?',['√2','√3','√5','√7','√11'],1,'√12√3 = √36 = 6.');
M(96,'İki merceğin büyütmesini çarpmak','Üslü ifadeler',39,'Mikroskobun iki ayrı büyütme oranını çarpıp bilimsel gösterimdeki küçük uzunluğu son görüntü uzunluğuna taşır.',['İki mercekli büyütme 4 × 40 = 160 kattır.','12,5 × 10⁻³ mm = 0,0125 mm; birim büyütmede değişmez.'],['Görüntü uzunluğu 0,0125 × 160 = 2 mm.','Sonuç D dir. 4 ile 40’ı toplamak veya 10⁻³ ü10³ olarak okumak büyüklük mertebesini bozar.'],'İki merceğin toplam 44 kat büyüttüğünü sanmak; birinin büyüttüğü görüntü ikincide yeniden büyür.','Ardışık ölçekler','Birleşik büyütme iki doğrusal oranının çarpımıdır; ardışık yüzde ve ölçek dönüşümleriyle aynı matematik yapısı vardır.','0,02 mm nesne 5 ve 30 kat büyüten iki mercekte kaç mm görünür?',['0,3','1','2','3','6'],3,'Toplam 150 kat; 0,02 × 150 = 3 mm.');
M(97,'Eşlenikle bölmenin doğru çarpımdan farkı','Köklü ifadeler',42,'Doğru çarpımda iki kare farkını, yanlış bölümde eşlenikle rasyonelleştirmeyi ayrı hesaplayıp sonuçların farkını bulur.',['(√10 + √6)(√10 − √6) = 10 − 6 = 4.','Bölümü eşlenikle genişletince pay(√10 + √6)² olur.'],['Yanlış sonuç(16 + 2√60)/4 = 4 + √15’tir.','Doğru 4’ten fazlalığı√15; B. Karşılaştırılanlar ilk sayı değil yapılan iki farklı işlemin sonucudur.'],'Eşlenikle çarpmanın sonucu sıfır sanmak veya bölümün paydasını rasyonelleştirmeden kökleri ayrı bölmek.','İki kare farkı','Eşlenik çarpımı köklü çapraz terimleri yok eder; kare toplamında ise bu terimler korunur. Yanlış bölümde payın iki terimli karesi olduğundan 2√60 terimi unutulursa hatalı biçimde fark sıfır bulunur.','(√7 + √3)(√7 − √3) kaçtır?',['2','3','4','√10','10'],2,'Eşlenik çarpımı 7 − 3 = 4.');
M(98,'Tabanı veya üssü üç olanlar','Üslü ifadeler',39,'Verilen sayıların 3’ün kuvveti ya da bir doğal sayının küpü olarak yazılabilmesini ayrı olasılıklar olarak sınar.',['Taban 3 ise 3ⁿ, üs 3 ise a³ biçimi gerekir.','Bu iki aile aynı değildir; ikisinden birine girmek yeterlidir.'],['8 = 2³,9 = 3²,64 = 4³,81 = 3⁴ koşulu sağlar.','36 ne 3’ün doğal kuvveti ne doğal sayının küpüdür; silinen 36, C. 36 = 6² yazılması yeterli değildir.'],'Herhangi bir üslü yazım bulunmasını yeterli saymak; tanımda özellikle taban veya üs 3 istenir.','Mantıksal veya','İki ayrı biçimden en az birini sağlayan sayılar kalır; her ikisini aynı anda sağlama zorunluluğu yoktur.','Hangisi tabanı veya üssü 3 olan doğal kuvvet biçiminde yazılamaz?',['27','81','125','216','100'],4,'27 = 3³,81 = 3⁴,125 = 5³,216 = 6³; 100 bu ailelerden değildir.');
M(99,'Köklü eşitlikte kullanılmayan sayı','Köklü ifadeler',42,'A√B = C√D eşitliğini karesini alarak tam sayı ilişkisine çevirip dört farklı sayının seçilmesini denetler.',['Pozitif sayılarda kare alma eşdeğerdir; A²B = C²D.','Kök içlerinin karesiz kısımları aynı olmalıdır; listede 2 ve 8 aynı√2 ailesindedir.'],['6√2 = 3√8 eşitliği sağlanır; 6,2,3,8 birer kez kullanılır.','Geriye 4 kalır; C. Diğer kök içi türleri aynı karesiz parçayı farklı sayı olarak eşleyemez.'],'Aynı sayıyı hem katsayı hem kök içinde tekrar kullanmak; soru dört sayının farklı seçilmesini şart koşar.','Karesiz parça','√8 = 2√2 gibi sadeleştirme görünüşte farklı köklerin aynı türden olduğunu açığa çıkarır.','x√3 = 2√12 ise x kaçtır?',['1','2','3','4','6'],3,'√12 = 2√3; sağ 4√3, dolayısıyla x = 4.');
M(100,'İki dönemde farklı nüfus artışı','Yüzde ve üslü ifadeler',51,'Dört yıl%10 ve sonraki dört yıl 1/11 oranlı bileşik artışın ortak 11 çarpanlarını sadeleştirir.',['İlk dönemde çarpan 11/10, ikinci dönemde 12/11’dir.','Her dönem dört sayım artışı içerir; 2015 başlangıcı artış sayısına dahil edilmez.'],['2023 nüfusu 810000·(11/10)⁴·(12/11)⁴ = 810000·(6/5)⁴.','810000 = 3⁴·2⁴·5⁴ olduğundan sonuç 2⁸3⁸ = 6⁸; D. Yıllık yüzdeler doğrudan toplanmaz.'],'2015–2023 aralığını dokuz artış saymak veya bütün sekiz yılda aynı artış oranını kullanmak.','Çarpan sadeleşmesi','Ardışık büyüme katsayılarının ortak pay–paydaları süreleri eşitse birlikte sadeleşerek hesaplamayı küçültür. Her sayımda artış bir önceki yılın güncellenmiş nüfusuna uygulanır.','100 birim önce%20, sonra 1/6 oranında artıyor. Son değer kaçtır?',['120','125','130','140','150'],3,'100 × 6/5 × 7/6 = 140; 6 çarpanı sadeleşir.');
M(101,'Karenin alanından doğal çarpanlar','Köklü ifadeler',42,'Kenar A√B iken alanın A²B olması koşulunu, A² nin 720’yi bölmesiyle sonlu doğal sayı çiftlerine indirger.',['(A√B)² = A²B = 720’dir.','720 = 2⁴·3²·5; kare çarpanın kökü A yalnız 1,2,3,4,6,12 olabilir.'],['Bu A değerlerinde B sırasıyla 720,180,80,45,20,5’tir.','A + B toplamları 721,182,83,49,26,17 olur. Seçeneklerde 127 bulunmaz; D. Alanla kenarı eşitlemek doğru değildir.'],'A ve B’yi herhangi iki 720 çarpanı sanmak; A’nın karesi alanı böler, A’nın yalnız kendisi değil.','Asal üsler','A² nin asal üsleri çift olduğundan 720’nin üsleri A’nın sınırlarını kesin belirler.','Kenar A√B, alan 72 ve A = 3 ise B kaçtır?',['2','4','6','8','24'],3,'9B = 72 olduğundan B = 8.');
M(102,'Ağaç biçimli mandal toplamları','Üslü ifadeler',39,'Her mandalın iki yeni mandal ürettiği düzende son sırayı değil başlangıçtan o adıma kadar bütün mandalları sayar.',['n inci sırada 2ⁿ⁻¹ yeni mandal bulunur.','n adımın toplamı 1 + 2+...+2ⁿ⁻¹ = 2ⁿ − 1’dir.'],['12. adım toplamı 2¹² − 1,10. adım toplamı 2¹⁰ − 1.','Fark 2¹² − 2¹⁰ = 2¹⁰(4 − 1) = 3·2¹⁰; A. Yalnız 12. ve 10. sıradaki yeni mandalları çıkarmak yarı değeri verir.'],'Kullanılan toplam ifadesini yalnız son sıradaki sayıya eşitlemek; ilk üç adımda 7 bilgisi toplam yorumunu doğrular.','Geometrik toplam','Ardışık iki toplamın ortak önceki terimleri farkta yok olur; yalnız 11. ve 12. sıralar kalır.','Aynı düzende 5. adım toplamı 3. adım toplamından kaç fazladır?',['12','16','20','24','28'],3,'31 − 7 = 24; eşdeğer olarak 8 + 16 = 24.');
M(103,'İki irrasyonelin tamsayı bölümü','Köklü ifadeler',42,'√720’nin seçeneklerdeki köklere oranını tek kök altında yazıp kök içinin tam kare olmasını test eder.',['√720/√t = √(720/t) dir.','İki sayı da irrasyonelken bölümleri tamsayı olabilir; aynı kök türü sadeleşebilir.'],['t = 5,20,45,80 için 720/t sırasıyla 144,36,16,9; karekökleri tamsayıdır.','t = 60 için bölüm√12 = 2√3’tür ve tamsayı değildir. Olamayan√60; D.'],'İrrasyonellerin bölümünün daima irrasyonel olacağını düşünmek veya kök içindeki bölmeyi dışarıdaki sayılarla karıştırmak.','Kök türlerinin sadeleşmesi','√720 = 12√5 biçimi özellikle√5 ailesindeki paydalarda tamsayı bölümün nasıl oluştuğunu gösterir.√60 ise 2√15 biçiminde farklı karesiz tür taşıdığı için aynı sadeleşmeyi sağlamaz.','√192/√12 kaçtır?',['2','3','4','6','8'],2,'Kök içinde 192/12 = 16;√16 = 4.');
M(104,'Üs kulesiyle kuvvetin kuvveti farklıdır','Üslü ifadeler',39,'a^(b^c) ile(a^b)^c ifadelerinin parantezlerini gerçekten hesaplayarak farklı sonuç üreten seçeneği arar.',['a^(b^c) önce b^c yi üs yapar.','(a^b)^c = a^(bc) dir; b^c ile bc her zaman eşit değildir.'],['B’de a = 2, b = 1, c = 3:ilk 2^(1³) = 2, ikinci(2¹)³ = 8 olur.','Diğer seçeneklerde a = 1, c = 1, b = 0 veya b^c = bc gibi özel eşitlikler sonuçları eşitler. Fark gösteren B.'],'Kuvvetin kuvveti kuralını üs kulesine parantezsiz uygulamak; yazımın gruplaması işlemin sonucunu değiştirir.','İşlem önceliği','Üslü ifadelerde üslerin nerede başladığı ve bittiği, çarpmadaki birleşme özelliği gibi serbest değildir.','2^(3²) ile(2³)² sırasıyla kaçtır?',['64,512','512,64','64,64','512,512','256,64'],1,'İlk 2⁹ = 512, ikinci 2⁶ = 64.');
M(105,'Aynı köklü iki ifadenin farkı','Köklü ifadeler',42,'Birinci ve ikinci işlemlerin farkında a√b terimlerinin silinmesini kullanıp b yi bulur, çarpım–bölüm sonuçlarının oranını sadeleştirir.',['(a√b + √b) − (a√b − √b) = 2√b dir.','Üçüncü işlem ab, dördüncü a dır; b > 0 olduğundan bölme tanımlıdır.'],['2√b = 12’den√b = 6, b = 36.','a = 2 için üçüncü 72, dördüncü 2; oran 72/2 = 36, E. a yı kullanmadan da(ab)/a = b bulunabilir.'],'12 lik farkı a nın katsayısına bağlamak veya√b·√b yi 2√b sanmak.','Ortak terimleri yok etme','İki benzer ifadenin farkı bilinmeyen ortak parçayı siler; istenen oran da ikinci bir sadeleşme sağlar. Böylece okunamayan b doğrudan sonuçlar arası farktan yeniden belirlenir.','a√b + √b ile a√b − √b farkı 10 ise b kaçtır?',['5','10','20','25','100'],3,'2√b = 10;√b = 5, b = 25.');
M(106,'İşlemci nesillerinde ortak kat','Üslü ifadeler',39,'İkinci ve dördüncü nesil arasında iki eş oran bulunduğunu kullanıp oranı karekökten, ilk nesli bölmeden bulur.',['Her neslin işlem sayısı öncekinin r katıdır.','Dördüncü/ikinci oranı r² dir; iki nesil farkı bir adım değildir.'],['r² = (4·10¹²)/10⁸ = 4·10⁴; pozitif r = 200.','Birinci nesil 10⁸/200 = 5·10⁵ işlem/s; B. 200 kat büyüme iki ardışık geçişte 40000 kat yapar.'],'İkinciyle dördüncü arasındaki toplam oranı doğrudan tek nesil oranı almak veya 10 üslerini yanlış çıkarmak.','Geometrik dizi','Eş nesil oranı diziyi geometrik yapar; aralarında iki indeks bulunan terimler oranın karesini verir.','İkinci terim 300, dördüncü 2700 olan pozitif ortak oranlı dizide birinci terim kaçtır?',['50','75','100','150','200'],2,'r² = 9, r = 3; ilk 300/3 = 100.');
M(107,'Dış karekökün altındaki toplam','Köklü ifadeler',42,'Beş ayrı karekökün tamamını kapsayan dış kökü okuyup bir terimi sıfırlayınca toplamın tam kare olmasını sınar.',['İç kökler√4,√9,√16,√36,√49 sırasıyla 2,3,4,6,7’dir.','Dış kökün tamsayı olması için içerideki toplam tam kare olmalıdır.'],['Başlangıç toplamı 22. Sayılardan birini 0 yapmak ilgili kök katkısını kaldırır.','36 yerine 0 yazınca 6 kaldırılır, toplam 16 ve dış kök 4 olur. Diğer çıkarmalar 20,19,18,15 tam kare değildir; D.'],'Dış kökü görmeyip beş tamsayının toplamını zaten tamsayı kabul etmek; kök çizgisinin kapsamı belirleyicidir.','Tam kare hedefi','Denenen değişiklikler bir toplamdan belirli katkılar çıkarır; yakın tam kare 16’yı hedeflemek hızlı çözüm sağlar.','√(√9 + √16 + √36) ifadesinde 36 yerine hangi sayı yazılırsa sonuç 3 olur?',['0','1','4','9','16'],2,'3 + 4 + √x = 9;√x = 2, x = 4.');
M(108,'İki çarpanın aynı anda bir artması','Sayı problemleri',47,'81 ildeki park ve park başına ağaç artışını çarpım farkı olarak yazıp çapraz artış terimini korur.',['İlk toplam 81 pa, son toplam 81(p + 1)(a + 1) dir.','(p + 1)(a + 1) = pa + p + a + 1; iki ayrı artışın ortak etkisi + 1 terimidir.'],['Son eksi ilk 81[(p + 1)(a + 1) − pa].','Parantez sadeleşince 81(p + a + 1); E. Yalnız eski parklara eklenen ağaçları saymak yeni parkların tüm ağaçlarını eksik bırakır.'],'Artışları yalnız 81p + 81a diye toplamak; yeni her parkın fazladan bir ağacı da vardır.','Çarpımın sonlu farkı','İki boyutta eşzamanlı birim artış, iki kenar şeridi ve bir köşe katkısı üretir.','10 yerde önce 3 park, park başına 5 ağaç planlı. İkisi de bir artarsa toplam fark kaçtır?',['30','50','80','90','100'],3,'10[(4·6) − (3·5)] = 10 × 9 = 90.');
M(109,'Evden arsaya aktarılan paranın kârı','Kâr zarar',52,'İlk satış gelirini ikinci alımın bütçesi yapıp yalnız arsa satışının kârını başlangıçtaki ev kârından ayırır.',['Ev alış birim fiyatı 3000, satış 3200 TL/m².','Arsa alış 20000, satış 25000 TL/dönüm; arsa başına kâr5000 TL dir.'],['450000/3000 = 150 m² ev,150 × 3200 = 480000 TL’ye satılır.','Bu para 24 dönüm arsa alır; arsa kârı 24 × 5000 = 120000 TL, D. Toplam ticaret kârı 150000 olsa da sorulan bu değildir.'],'İlk ev kârını da arsa kârına eklemek veya 450000’i doğrudan arsa alım bütçesi sanmak.','Ardışık nakit akışı','Bir işlemin brüt geliri sonraki işlemin maliyeti olur; kâr her aşamanın kendi alış–satış farkıdır.','120000 TL ile birimi 10000 TL arsa alınıp 12500’den satılıyor. Yalnız arsa kârı kaç TL?',['15000','20000','25000','30000','35000'],3,'12 birim alınır; her biri 2500 TL kâr, toplam 30000.');
M(110,'İki buluşmada aynı yaş ortalaması','Yaş problemleri',49,'İlk üç kişinin yaş toplamının zamanla 3t artmasını ve çocuklarla aralarındaki sabit toplam fark 90’ı birlikte kullanır.',['Başlangıç yetişkin yaş toplamı 3 × 20 = 60.','t yıl sonra yetişkin toplamı 60 + 3t; üç ebeveyn–çocuk yaş farkı toplamı 28 + 30 + 32 = 90’dır.'],['Çocukların toplamı(60 + 3t) − 90 = 3t − 30.','Altı kişinin ortalaması 20 olduğundan toplam 120; 30 + 6t = 120, t = 15 yıl, A. Çocukların başlangıçta doğmuş olması gerekmez.'],'20 ortalamasını her ebeveynin kesin yaşı sanmak veya geçen sürede yalnız yetişkinlerin toplamına t eklemek.','Toplamla çalışma','Bireysel yaşlar bilinmese de ortalama ve toplam farklar yeterlidir; altı ayrı bilinmeyen gereksizdir.','Üç kişinin toplam yaşı 60. Beş yıl sonra aynı üç kişinin toplamı kaçtır?',['65','70','75','80','90'],2,'Her biri 5 yaş büyür; toplam 15 artarak 75 olur.');
M(111,'Para üstünü meyveyle ödeme','Denklem sistemi',33,'İlk para üstünün 1 kg kiraz fiyatına, ek 3 TL ile 1 kg muz fiyatına eşit olduğunu doğru alışveriş toplamıyla birleştirir.',['İlk alışveriş bedeli 3(K + M); para üstü 30 − 3(K + M).','Manavın önerisi para üstü K, müşterinin önerisi M = K + 3 demektir.'],['s = K + M alırsak K = 30 − 3s, M = 33 − 3s.','Toplayınca s = 63 − 6s; 7s = 63 ve s = 9 TL/kg fiyat toplamı, E. 30 TL tamamı harcanmış değildir.'],'Manavın bozuk parası olmamasını para üstü sıfır diye yorumlamak veya ek 3 TL’yi ilk alışverişe geriye eklemek.','Eşdeğer ödeme','Nakit yerine mal verilmesi parasal eşitlik oluşturur; miktarı 1 kg olduğu için doğrudan birim fiyatla eşlenir.','Para üstü 4 TL yerine 1 kg X veriliyor. 2 TL daha eklenip 1 kg Y alınıyorsa Y fiyatı kaçtır?',['2','4','5','6','8'],3,'Y’nin bedeli mevcut 4 TL alacakla ek 2 TL’nin toplamı 6 TL dir.');
M(112,'Ayakkabı numaralarında doğrusal dönüşüm','Oran orantı',46,'İki standardın(34,7) ve(46,13) uçlarını kullanarak bir standardın artışını diğerine orantılar.',['Doğrusal ilişkide eşit B artışları eşit A artışı verir.','A 12 birim artarken B 6 birim artar; A’nın değişim katsayısı 2’dir.'],['B = 11,5 değeri 7’den 4,5 fazladır; A, 34’ten 2 × 4,5 = 9 artar.','A = 43; A. Eşdeğer denklem A = 2B+20’dir; başlangıç sabiti atılamaz.'],'A/B oranını sabit sanmak; doğrusal ilişki her zaman doğru orantı değildir, burada sabit 20 vardır.','Eğim ve kesişim','İki eşleşme dönüşümün eğimini ve başlangıç değerini belirler; birimler değişse de doğrusal yapı korunur.','A = 3B+5 sisteminde B = 8 ise A kaçtır?',['19','21','24','27','29'],4,'3 × 8 + 5 = 29.');
M(113,'Tuş konumundan rakam eşleştirmek','Sayı problemleri',47,'İki hesap makinesinin farklı tuş düzenlerinde aynı konumlara basılmasını basamak bazlı dönüşüm olarak kullanır.',['Solda 2 tuşunun konumu sağda 8,9’un konumu sağda 3’tür.','Burcu nun ilk topladığı sayı 83 olur; toplama işareti ve 0 aynı konumdadır.'],['Burcu sonucu 95 ise ikinci dönüştürülmüş sayı 95 − 83 = 12.','Sağdaki 1 ve 2 konumları solda 7 ve 8’e karşılık gelir; Defne 78 yazmıştır. 29 + 78 = 107; D.'],'29’un basamaklarını yalnız ters çevirmek veya iki makinede rakamlar aynı konumdaymış gibi işlem yapmak.','Birebir kodlama','Tuş haritası her rakamı ayrı dönüştürür; sonucu ters çözmek için aynı harita geriye uygulanır.','Tuş dönüşümü 2→8,9→3,7→1,8→2 ise 29 + 78 diğer makinede kaç görünür?',['85','90','95','103','107'],2,'29→83,78→12; toplam 95.');
M(114,'İki ardışık yüzde kaybı','Yüzde problemleri',51,'Tarife göre hedeflenen 720 gramdan başlangıç yaş mısır miktarını bulup doğru%30 kurutma kaybıyla gerçek ürünü hesaplar.',['Yanlış tarifte kalan oran 0,8 × 0,9 = 0,72’dir.','Gerçekte kalan oran 0,7 × 0,9 = 0,63; kayıplar farklı aşamaların kütlesine uygulanır.'],['Başlangıç mısır 720/0,72 = 1000 gram alınmıştır.','Gerçek patlamış mısır 1000 × 0,63 = 630 gram; A. 20 ve 10 kaybını doğrudan%30 diye toplamak yanlış sonuç verir.'],'Yeni doğru oranı 720 gramın kendisine uygulamak; 720 hedef üründür, başlangıç yaş miktar değildir.','Ardışık oranlar','İkinci yüzde ilk kayıptan sonra kalan maddeye uygulanır; toplam kalan oran çarpımla bulunur.','1000 g ürün önce%25, sonra%20 kaybediyor. Kaç g kalır?',['500','550','600','650','750'],2,'1000 × 0,75 × 0,80 = 600 g.');
M(115,'İç içe bardakların doğrusal yüksekliği','Sayı problemleri',47,'İlk bardağın tam boyunu sonraki bardakların küçük sabit artışından ayırıp kulelerin toplamını tek kuleyle eşler.',['n bardak yüksekliği H(n) = h + (n − 1)d dir.','İlk bardak tam h ekler; her ek bardak yalnız d kadar yükseltir.'],['H(6)+H(9) = H(18)’den 2h + 13d = h + 17d; h = 4d.','H(8)+H(12) = 2h + 18d = 26d. H(n) = (n + 3)d olduğundan n + 3 = 26, n = 23; A.'],'Kule yüksekliklerini doğrudan bardak sayılarıyla orantılı saymak; 6 + 9’un 18’e eşitliği başlangıç yüksekliği etkisini gösterir.','Sabit terimli doğrusal model','Kuleleri birleştirmek iki kez sayılan ilk bardak payı nedeniyle sayıların doğrudan toplamı değildir.','H(n) = 5 + (n − 1) cm ise H(4)+H(6) hangi kuleye eşittir?',['10','12','13','14','15'],3,'H(4) = 8,H(6) = 10, toplam 18; H(n) = n + 4 = 18’den n14.');
M(116,'Yalnız bir veya üç içecek alanlar','Sayı problemleri',47,'Hazırlanan 75 bardaktan kalanları çıkarıp, iki çeşit alan olmadığı bilgisini toplam tüketim denklemine taşır.',['Tüketilenler 18 mandalina,17 nar,16 portakal; toplam 51 bardaktır.','Herkes en az bir çeşit aldığı, aynı türden iki almadığı ve iki çeşit alan olmadığı için kişi 1 veya 3 bardak alır.'],['Üç çeşit alan x ise kalan 25 − x kişi tek bardak alır.','3x + (25 − x) = 51; 2x = 26, x = 13 kişi, D. Her bir fazla iki bardak bir üçlü alıcıyı gösterir.'],'Kalan 7 + 8 + 9 = 24 bardağı kişi sayısı diye çıkarmak veya iki içecek alanları serbest bırakmak.','Taban tüketim','Herkese birer bardak verilmiş gibi 25 temel tüketim ayrılır; fazla 26 bardak ikişerli farklarla 13 kişiyi belirler.','20 kişi 1 veya 3 bardak almış, toplam 32 bardak tüketilmiş. Üç bardak alan kaçtır?',['4','5','6','7','8'],2,'20 + 2x = 32; x = 6.');
M(117,'Kalem oklarından zorunlu sıralama','Eşitsizlikler',32,'Her kalem ucunu küçükten büyüğe yönelen karşılaştırma okuyup 9 farklı rakamı kısmi sıralama zincirine yerleştirir.',['Okun gösterdiği topun değeri diğer uçtakinden büyüktür.','Uzun zincir F < I < H < G < D ve A, E’nin D ile B arasında olması sıralamayı büyük ölçüde belirler.'],['Şekilden F < I < H < G < D < A < B < C ve D < E < B elde edilir.','1–9 rakamlarıyla F = 1, I = 2, H = 3, G = 4, D = 5, B = 8, C = 9; A ve E, 6 ile 7’yi paylaşır. A + E + G = 13 + 4 = 17; E.'],'Kalemin silgisini ok ucu sanmak veya A ile E’nin ayrı değerleri belirlenemeyince toplamın da bulunamayacağını düşünmek.','Kısmi sıra','İki elemanın kendi aralarındaki düzeni belirsiz kalabilir; kapladıkları rakam kümesi sabitse toplamları yine kesindir.','1–5 değerleri için A < B < C ve B < D < E, C < E ise A + B + E kaçtır?',['7','8','9','10','11'],1,'A = 1, B = 2, E = 5 olmak zorundadır; C ve D, 3 ile 4’ü paylaşır, toplam 8.');
M(118,'İndirimi açan ek ürün','Yüzde ve fiyat problemleri',51,'Eklenen ürünün bedeliyle beş eski ürüne yapılan toplam 10 TL indirimi ayrı yazarak son 43 TL ödemeyi modeller.',['Başlangıç toplam 45 TL dir.','Beş ürüne 2 şer TL indirim toplam 10 TL azaltır; son alınan ürüne indirim uygulanmaz.'],['Ek ürün x TL ise 45 + x − 10 = 43.','x = 8 TL; D. İndirim öncesi toplam 53 TL olduğu için 50 TL eşiği de sağlanır; son ödeme 43’ün eşik altına inmesi engel değildir.'],'50 TL eşiğini indirim sonrası ödeme için istemek veya yeni ürünü de altıncı indirimli ürün saymak.','Koşulun kontrolü','Denklem çözümü fiyatı bulur; kampanya eşiğini gerçekten açtığını doğrulamak modelin tutarlılık adımıdır.','Başlangıç 46 TL, ek ürünle dört eski ürüne 3 TL indirim sonrası 42 TL ödeniyor. Ek ürün kaç TL?',['6','7','8','9','10'],2,'46 + x − 12 = 42; x = 8 TL.');
M(119,'Otoparkta toplam hareket ve net doluluk','Denklem sistemi',33,'İki göstergedeki boş yerleri toplayıp boşluk azalmasını giriş–çıkış farkına dönüştürerek toplam 51 hareketle birlikte çözer.',['İlk boş yer 26 + 6 = 32, son boş yer 2 + 9 = 11’dir.','Boşluk 21 azalırsa park etmiş araç sayısı 21 artmıştır; giriş eksi çıkış 21’dir.'],['G + Ç = 51 ve G − Ç = 21.','Toplayınca 2G = 72, G = 36 araç; D. İkinci kattaki boşluğun artması tek başına bütün otoparkın boşaldığı anlamına gelmez.'],'İlk dijital 26’yı 25 okumak veya boş yer azalmasını giriş sayısının kendisi sanıp çıkan araçları unutmak.','Stok–akış denklemi','Başlangıç ve son stok net farkı verir; toplam hareket ayrı bilgiyle iki bilinmeyeni ayırır.','Giriş + çıkış 40, park eden araç sayısı 12 artmış. Giriş kaçtır?',['14','20','24','26','28'],3,'G + Ç40, G − Ç12;2G52,G26.');
M(120,'Hediyede yarım pay ödeyenler','Kesir problemleri',48,'Yedi kişinin eş payından üçünün yarısını ödemesini, eksik kalan toplamı dört kişinin eşit tamamlamasıyla ilişkilendirir.',['Hediye T ise planlanan kişi payı T/7’dir.','Üç kişinin eksik ödediği toplam 3·T/14; dört kişinin her biri bunun dörtte birini tamamlar.'],['Her tam ödeyenin fazladan miktarı 3T/56’dır.','3T/56 = 6’dan T = 112 TL; A. Üç yarım ödeyen 8 er, dört tamamlayan 22 şer TL verir; 24 + 88 = 112 toplamını doğrular.'],'Eksik üç yarım payı yedi kişiye yeniden dağıtmak; metin yalnız kalan dört arkadaşın tamamladığını belirtir.','Paylaştırmada korunma','Eksik ödenen toplamla diğerlerinin fazladan ödediği toplam eşittir; hediyenin bedeli değişmez.','Altı kişilik hediyede iki kişi yarım pay ödüyor, kalan dört kişi 5 TL fazla veriyor. Hediye kaç TL?',['60','90','100','120','150'],3,'Eksik toplam bir tam paydır ve 4 × 5 = 20 TL; kişi payı 20, hediye 6 × 20 = 120 TL.');
window. EXAM_ANALYSES={...(window. EXAM_ANALYSES||{}),...rows};
})();
